def _place_names_match(a: str, b: str) -> bool:
    """FIX #301: GAMARDŻOBA vs GAMARDŻOBY is the same restaurant."""
    aa = " ".join((a or "").lower().split())
    bb = " ".join((b or "").lower().split())
    if not aa or not bb:
        return False
    if aa == bb:
        return True
    shorter, longer = (aa, bb) if len(aa) <= len(bb) else (bb, aa)
    # FIX #302: "pergola" is 7 chars — still the same stop as
    # "Pergola przy Hali Stulecia". Keep ≥7 so "wyspa"/"park" do not collide.
    if len(shorter) >= 7 and shorter in longer:
        return True

    def _stem(s: str) -> str:
        for src, dst in (
            ("ż", "z"), ("ź", "z"), ("ó", "o"), ("ł", "l"),
            ("ą", "a"), ("ę", "e"), ("ć", "c"), ("ń", "n"), ("ś", "s"),
        ):
            s = s.replace(src, dst)
        s = s.replace(" ", "")
        for suf in ("ego", "owi", "ami", "ach", "em", "om", "ie", "y", "i", "a", "e"):
            if len(s) > 7 and s.endswith(suf):
                return s[:-len(suf)]
        return s

    sa, sb = _stem(aa), _stem(bb)
    if sa == sb:
        return True
    if len(sa) >= 7 and len(sb) >= 7 and (sa.startswith(sb) or sb.startswith(sa)):
        return True
    return False


def _timeline_satellite_kind(name: str) -> Optional[str]:
    """FIX #281: which Wrocław day-trip region a stop belongs to, if any."""
    nm = (name or "").lower()
    if _is_olawa_stop_name(nm):
        return "olawa"
    if _is_wojslawice_stop_name(nm):
        return "wojslawice"
    if any(k in nm for k in (
        "ząbkowic", "zabkowic", "frankenstein",
        "krzywa wieża", "krzywa wieza",
    )):
        return "zabkowice"
    if _is_brzeg_stop_name(nm):
        return "brzeg"
    if _is_near_satellite_stop_name(nm):
        return "near"
    if _is_ojcow_stop_name(nm) or any(
        k in nm for k in ("eliaszówk", "eliaszowk", "czerna")
    ):
        return "ojcow"
    if _is_bochnia_stop_name(nm):
        return "bochnia"
    if _is_wieliczka_stop_name(nm):
        return "wieliczka"
    if "muzeum lotnictwa" in nm or "gojump" in nm or "mateczn" in nm:
        return "czyzyny"
    if _is_tenczyn_stop_name(nm):
        return "tenczyn"
    if _is_wisnicz_stop_name(nm):
        return "wisnicz"
    if _is_zabrze_stop_name(nm):
        return "zabrze"
    if (
        _is_gliwice_stop_name(nm)
        or "willa caro" in nm
        or "park chopina" in nm
        or "park chrobrego" in nm
        or "park pileckiego" in nm
        or "park pilecki" in nm
        or "pileckiego" in nm
        or "palmiarnia miejska" in nm
    ):
        return "gliwice"
    if "wodny park tychy" in nm or ("tychy" in nm and "wodny" in nm):
        return "tychy"
    if any(k in nm for k in (
        "park śląski", "park slaski", "chorzów", "chorzow", "etnograficzn",
        "giszowiec", "szyb wilson", "nikiszowiec",
    )):
        return "chorzow"
    if "nemo" in nm:
        return "dabrowa"
    if _is_gniezno_stop_name(nm):
        return "gniezno"
    if _is_kornik_stop_name(nm):
        return "kornik"
    if _is_rogalin_stop_name(nm):
        return "rogalin"
    if _is_puszczykowo_stop_name(nm):
        return "puszczykowo"
    if any(k in nm for k in (
        "dziekanowic", "lednick", "ostrów lednick", "ostrow lednick",
    )):
        return "lednica"
    if "pobiedzisk" in nm:
        return "pobiedziska"
    if any(k in nm for k in (
        "strzeszyn", "jezioro strzeszyń", "jezioro strzeszyn", "wodziczk",
    )):
        return "strzeszyn"
    if _is_kampinos_stop_name(nm):
        return "kampinos"
    if _is_czersk_stop_name(nm):
        return "czersk"
    if _is_sochaczew_stop_name(nm):
        return "sochaczew"
    return None


def _day_items_satellite_kind(items: list) -> Optional[str]:
    counts: Dict[str, int] = {}
    for it in items or []:
        if not _is_timeline_attraction(it):
            continue
        k = _timeline_satellite_kind(getattr(it, "name", "") or "")
        if k:
            counts[k] = counts.get(k, 0) + 1
    if not counts:
        return None
    return max(counts, key=counts.get)


