def _poznan_seed_coords(name: str) -> Optional[tuple]:
    """FIX #307: default lat/lng so first hops / satellite drives can be built."""
    nm = (name or "").lower()
    if "stare zoo" in nm:
        return _POZNAN_STARE_ZOO_COORDS
    if "nowe zoo" in nm:
        return _POZNAN_NOWE_ZOO_COORDS
    if "rusałk" in nm or "rusalk" in nm:
        return _POZNAN_RUSALKA_COORDS
    if "brama poznania" in nm:
        return _POZNAN_BRAMA_COORDS
    if "ostrów tumski" in nm or "ostrow tumski" in nm:
        return _POZNAN_OSTROW_TUMSKI_COORDS
    if _is_rogalin_stop_name(nm):
        return _ROGALIN_DEFAULT_COORDS
    if any(k in nm for k in ("lednick", "dziekanowic")):
        return _LEDNICA_DEFAULT_COORDS
    return None


def _katowice_seed_coords(name: str) -> Optional[tuple]:
    """FIX #308: Chorzów / Giszowiec / Tychy / Gliwice seeds for first hops."""
    nm = (name or "").lower()
    if "park śląski" in nm or "park slaski" in nm:
        return _KATOWICE_PARK_SLASKI_COORDS
    if "etnograficzn" in nm:
        return _KATOWICE_ETNO_COORDS
    if "szyb wilson" in nm:
        return _KATOWICE_WILSON_COORDS
    if "giszowiec" in nm:
        return _KATOWICE_GISZOWIEC_COORDS
    if "paprocan" in nm:
        return _KATOWICE_PAPROCANY_COORDS
    if "muzeum historii katowic" in nm:
        return _KATOWICE_MHK_COORDS
    if "wodny park" in nm and "tych" in nm:
        return _TYCHY_WODNY_COORDS
    if any(k in nm for k in (
        "park chopina", "park chrobrego", "willa caro", "sensorycz",
        "palmiarnia",
    )):
        return _GLIWICE_DEFAULT_COORDS
    return None


def _krakow_seed_coords(name: str) -> Optional[tuple]:
    """FIX #309: Lotnictwo / GOjump / Bulwary seeds for first hops."""
    nm = (name or "").lower()
    if "muzeum lotnictwa" in nm:
        return _KRAKOW_LOTNICTWA_COORDS
    if "gojump" in nm or "mateczn" in nm:
        return _KRAKOW_GOJUMP_COORDS
    if "bulwary" in nm:
        return _KRAKOW_BULWARY_COORDS
    if "schindler" in nm:
        return _KRAKOW_SCHINDLER_COORDS
    return None


def _seed_first_stop_coords(name: str) -> Optional[tuple]:
    return (
        _poznan_seed_coords(name)
        or _katowice_seed_coords(name)
        or _krakow_seed_coords(name)
    )


def _is_kampinos_stop_name(name: str) -> bool:
    nm = (name or "").lower()
    return any(k in nm for k in (
        "kampinos", "łomna", "lomna", "palmiry", "granica", "ośrodek w granicy",
        "osrodek w granicy",
    ))


def _is_czersk_stop_name(name: str) -> bool:
    nm = (name or "").lower()
    return any(k in nm for k in (
        "czersk", "zamek w czersku", "góra kalwaria", "gora kalwaria",
    ))


def _is_sochaczew_stop_name(name: str) -> bool:
    nm = (name or "").lower()
    return any(k in nm for k in (
        "sochaczew", "żelazowa", "zelazowa",
    ))


def _is_puszczykowo_stop_name(name: str) -> bool:
    nm = (name or "").lower()
    return any(k in nm for k in _PUSZCZYKOWO_NAME_MARKERS)


def _is_poznan_old_town_name(name: str) -> bool:
    """FIX #286: Ratusz + Stary Rynek are one microcluster."""
    nm = (name or "").lower()
    return any(k in nm for k in (
        "ratusz w poznaniu",
        "stary rynek w poznaniu",
    ))


# FIX #261: origin for the "day_start → first POI" leg when no hotel is given.
_CITY_CENTER_COORDS: Dict[str, tuple] = {
    "wrocław": (51.1079, 17.0385),
    "wroclaw": (51.1079, 17.0385),
    "warszawa": (52.2297, 21.0122),
    "warsaw": (52.2297, 21.0122),
    "kraków": (50.0647, 19.9450),
    "krakow": (50.0647, 19.9450),
    "poznań": (52.4064, 16.9252),
    "poznan": (52.4064, 16.9252),
    "gdańsk": (54.3520, 18.6466),
    "gdansk": (54.3520, 18.6466),
    "katowice": (50.2649, 19.0238),
}


def _city_center_coords(city: str) -> Optional[tuple]:
    c = (city or "").strip().lower()
    if not c:
        return None
    if c in _CITY_CENTER_COORDS:
        return _CITY_CENTER_COORDS[c]
    for key, coords in _CITY_CENTER_COORDS.items():
        if key in c:
            return coords
    return None


def _item_type_value(item) -> str:
    """Normalize ItemType enum / raw string."""
    t = getattr(item, "type", None)
    if hasattr(t, "value"):
        return str(t.value)
    return str(t or "")


def _is_timeline_attraction(item) -> bool:
    return _item_type_value(item) == ItemType.ATTRACTION.value


def _find_next_attraction(items: list, start_idx: int):
    """FIX #235: next attraction after index, skipping meals/free_time."""
    for j in range(start_idx + 1, len(items)):
        if _is_timeline_attraction(items[j]):
            return items[j]
    return None


def _find_prev_attraction(items: list, start_idx: int):
    """Last attraction before index (skips meals/transits)."""
    for j in range(start_idx - 1, -1, -1):
        if _is_timeline_attraction(items[j]):
            return items[j]
    return None


def _meal_primary_restaurant_name(item) -> str | None:
    """FIX #251: primary restaurant suggestion name for lunch/dinner."""
    tv = _item_type_value(item)
    if tv not in (ItemType.LUNCH_BREAK.value, ItemType.DINNER_BREAK.value):
        return None
    sugs = getattr(item, "suggestions", None) or []
    if not sugs:
        return None
    s0 = sugs[0]
    if isinstance(s0, dict):
        name = (s0.get("name") or "").strip()
    else:
        name = (getattr(s0, "name", None) or "").strip()
    return name or None


def _find_meal_restaurant_between(items: list, transit_idx: int, next_attraction) -> str | None:
    """Restaurant between this transit and the next attraction (route via meal)."""
    for j in range(transit_idx + 1, len(items)):
        it = items[j]
        if it is next_attraction or _is_timeline_attraction(it):
            break
        rn = _meal_primary_restaurant_name(it)
        if rn:
            return rn
    return None


def _find_prev_meal_restaurant(items: list, transit_idx: int) -> str | None:
    """If a meal before this transit already finished, return its restaurant.

    FIX #254: ignore meals that are only later in clock time (client: Ciao Italia
    as origin before the lunch slot).
    """
    try:
        transit_start = time_to_minutes(getattr(items[transit_idx], "start_time", None) or "00:00")
    except Exception:
        transit_start = None
    for j in range(transit_idx - 1, -1, -1):
        it = items[j]
        if _is_timeline_attraction(it):
            return None
        rn = _meal_primary_restaurant_name(it)
        if rn:
            if transit_start is None:
                return rn
            try:
                meal_end = time_to_minutes(
                    getattr(it, "end_time", None) or getattr(it, "start_time", None) or "00:00"
                )
            except Exception:
                return rn
            # Only route from a restaurant the guest has already visited.
            if meal_end <= transit_start + 2:
                return rn
            return None
        if _item_type_value(it) == ItemType.TRANSIT.value:
            continue
    return None


def _is_urban_trip(context: Dict[str, Any]) -> bool:
    from app.domain.planner.city_copy import is_city_tourism_trip
    rt = str(context.get("region_type") or "").lower()
    return rt in ("city", "urban") or is_city_tourism_trip(context)


def _day_afternoon_free_time_min(items: list) -> int:
    """Sum free_time minutes before 16:00 (client: mega afternoon blocks)."""
    total = 0
    for it in items:
        if getattr(it, "type", None) != ItemType.FREE_TIME:
            continue
        st = getattr(it, "start_time", None)
        if st and time_to_minutes(st) < 960:
            total += int(getattr(it, "duration_min", 0) or 0)
    return total


def _strip_leading_free_time(items: list) -> list:
    """FIX #222/#229: remove morning free_time before the first attraction."""
    if not items:
        return items
    first_attr = next(
        (i for i, it in enumerate(items)
         if getattr(it, "type", None) == ItemType.ATTRACTION),
        None,
    )
    if first_attr is None:
        return items
    out = []
    for i, it in enumerate(items):
        if i < first_attr and getattr(it, "type", None) == ItemType.FREE_TIME:
            continue
        out.append(it)
    return out


def _strip_trailing_free_time(items: list, *, max_min: int = 30) -> list:
    """FIX #229/#230: trim long free_time blocks at end of day (before day_end)."""
    if not items:
        return items
    last_attr = None
    for i in range(len(items) - 1, -1, -1):
        if getattr(items[i], "type", None) == ItemType.ATTRACTION:
            last_attr = i
            break
    if last_attr is None:
        return items
    out = []
    for i, it in enumerate(items):
        if i > last_attr and getattr(it, "type", None) == ItemType.FREE_TIME:
            dur = int(getattr(it, "duration_min", 0) or 0)
            if dur > max_min:
                continue
        out.append(it)
    return out


def _trim_long_free_time_blocks(items: list, *, max_min: int = 30) -> list:
    """FIX #230: cap any single free_time block in the middle/end of day."""
    if not items:
        return items
    from app.domain.planner.time_utils import time_to_minutes, minutes_to_time
    out = []
    for it in items:
        if getattr(it, "type", None) == ItemType.FREE_TIME:
            dur = int(getattr(it, "duration_min", 0) or 0)
            if dur > max_min:
                st = getattr(it, "start_time", None)
                if st and hasattr(it, "end_time"):
                    end_m = time_to_minutes(st) + max_min
                    setattr(it, "duration_min", max_min)
                    setattr(it, "end_time", minutes_to_time(end_m))
        out.append(it)
    return out


def _trim_midday_free_time_blocks(items: list, *, max_min: int = 30) -> list:
    """FIX #275: cap mid-day free_time only — afternoon tail stays."""
    if not items:
        return items
    from app.domain.planner.time_utils import time_to_minutes, minutes_to_time
    content_end = _timeline_content_end_minutes(items)
    out = []
    for it in items:
        if getattr(it, "type", None) != ItemType.FREE_TIME:
            out.append(it)
            continue
        dur = int(getattr(it, "duration_min", 0) or 0)
        st = getattr(it, "start_time", None)
        try:
            st_m = time_to_minutes(st) if st else 0
        except Exception:
            st_m = 0
        trailing = content_end is not None and st_m >= content_end - 2
        afternoon = st_m >= 15 * 60 + 30
        if dur > max_min and not trailing and not afternoon:
            if st and hasattr(it, "end_time"):
                end_m = st_m + max_min
                try:
                    it = it.model_copy(update={
                        "duration_min": max_min,
                        "end_time": minutes_to_time(end_m),
                    })
                except Exception:
                    setattr(it, "duration_min", max_min)
                    setattr(it, "end_time", minutes_to_time(end_m))
        out.append(it)
    return out


def _trim_gap_after_day_start(items: list, *, max_gap_min: int = 12) -> list:
    """FIX #229/#233: first attraction should follow day_start within max_gap_min."""
    if not items:
        return items
    from app.domain.planner.time_utils import time_to_minutes as _ttm
    day_start_min = None
    first_attr_idx = None
    for i, it in enumerate(items):
        if getattr(it, "type", None) == ItemType.DAY_START:
            t = getattr(it, "time", None)
            if t:
                day_start_min = _ttm(t)
        if first_attr_idx is None and getattr(it, "type", None) == ItemType.ATTRACTION:
            first_attr_idx = i
    if day_start_min is None or first_attr_idx is None:
        return items
    out = []
    for i, it in enumerate(items):
        if (
            i < first_attr_idx
            and getattr(it, "type", None) == ItemType.FREE_TIME
            and day_start_min is not None
        ):
            st = getattr(it, "start_time", None)
            if st and _ttm(st) - day_start_min <= max_gap_min:
                continue
        out.append(it)
    return out


def _cap_total_day_free_time(items: list, *, max_total: int = 25) -> list:
    """FIX #231/#233/#234: limit total free_time minutes per day (client: hour+ gaps).

    FIX #261: never drop evening blocks (start ≥ 16:00) — those are the named
    tails that close client idle-tail defects; trim midday fillers first.
    """
    ft_indices = [
        i for i, it in enumerate(items)
        if getattr(it, "type", None) == ItemType.FREE_TIME
    ]
    total = sum(int(getattr(items[i], "duration_min", 0) or 0) for i in ft_indices)
    if total <= max_total:
        return items
    out = list(items)

    def _drop_key(idx: int) -> tuple:
        it = items[idx]
        try:
            st = time_to_minutes(getattr(it, "start_time", None) or "00:00")
        except Exception:
            st = 0
        evening = 1 if st >= 16 * 60 else 0
        dur = int(getattr(it, "duration_min", 0) or 0)
        # Drop smallest non-evening first; evenings last (and only if still over).
        return (evening, dur)

    for i in sorted(ft_indices, key=_drop_key):
        if total <= max_total:
            break
        dur = int(getattr(out[i], "duration_min", 0) or 0)
        total -= dur
        out[i] = None
    return [it for it in out if it is not None]


def _lunch_latest_min(user: Optional[Dict[str, Any]] = None) -> int:
    """FIX #272: family lunch should land by 14:00, others by 14:30."""
    if str((user or {}).get("target_group") or "") == "family_kids":
        return 14 * 60
    return 14 * 60 + 30


def _fix_late_lunch(items: list, *, latest_min: int = 840) -> list:
    """FIX #231: move lunch_break that starts after 14:00 to 12:30."""
    from app.domain.planner.time_utils import time_to_minutes, minutes_to_time
    out = []
    for it in items:
        if _item_type_value(it) == ItemType.LUNCH_BREAK.value:
            st = getattr(it, "start_time", None)
            if st and time_to_minutes(st) > latest_min:
                dur = int(getattr(it, "duration_min", 0) or 40)
                new_dur = min(dur, 60)
                try:
                    it = it.model_copy(update={
                        "start_time": "12:30",
                        "end_time": minutes_to_time(time_to_minutes("12:30") + new_dur),
                        "duration_min": new_dur,
                    })
                except Exception:
                    setattr(it, "start_time", "12:30")
                    setattr(it, "end_time", minutes_to_time(time_to_minutes("12:30") + new_dur))
                    if hasattr(it, "duration_min"):
                        setattr(it, "duration_min", new_dur)
        out.append(it)
    return out


def _reorder_leading_lunch(items: list) -> list:
    """FIX #255/#259: day must not open with lunch — park attraction first.

    FIX #259 Wrocław: sparse afternoons left lunch as the first real timeline
    block (13:05 lunch, 14:44 Hala). Pull the first attraction into the morning
    window so the day never opens on a meal.
    """
    if not items:
        return items
    from app.domain.planner.time_utils import time_to_minutes, minutes_to_time

    lunch_idx = None
    first_attr_idx = None
    day_start_min = None
    for i, it in enumerate(items):
        t = getattr(it, "type", None)
        tv = str(getattr(t, "value", t) or "")
        if tv == ItemType.DAY_START.value or t == ItemType.DAY_START:
            ds = getattr(it, "time", None) or getattr(it, "start_time", None)
            if ds:
                try:
                    day_start_min = time_to_minutes(ds)
                except Exception:
                    pass
        if lunch_idx is None and (
            t == ItemType.LUNCH_BREAK or tv == ItemType.LUNCH_BREAK.value
        ):
            lunch_idx = i
        if first_attr_idx is None and (
            t == ItemType.ATTRACTION or tv == ItemType.ATTRACTION.value
        ):
            first_attr_idx = i
    if lunch_idx is None or first_attr_idx is None:
        return items

    lunch = items[lunch_idx]
    attr = items[first_attr_idx]
    lunch_st = getattr(lunch, "start_time", None)
    attr_st = getattr(attr, "start_time", None)
    try:
        lunch_m = time_to_minutes(lunch_st) if lunch_st else None
        attr_m = time_to_minutes(attr_st) if attr_st else None
    except Exception:
        return items

    # Case A: lunch listed/timed before first attraction (classic leading lunch).
    leading = lunch_idx < first_attr_idx or (
        lunch_m is not None and attr_m is not None and lunch_m <= attr_m
    )
    if not leading:
        return items

    # Pull attraction into the morning before lunch.
    anchor = day_start_min if day_start_min is not None else 9 * 60
    new_attr_st = anchor + 15
    dur = int(getattr(attr, "duration_min", 0) or 0)
    if dur <= 0 and attr_st and getattr(attr, "end_time", None):
        try:
            dur = max(
                30,
                time_to_minutes(attr.end_time) - time_to_minutes(attr_st),
            )
        except Exception:
            dur = 60
    dur = max(30, dur)
    new_attr_en = new_attr_st + dur
    try:
        items[first_attr_idx] = attr.model_copy(update={
            "start_time": minutes_to_time(new_attr_st),
            "end_time": minutes_to_time(new_attr_en),
            "duration_min": dur,
        })
        attr = items[first_attr_idx]
    except Exception:
        try:
            attr.start_time = minutes_to_time(new_attr_st)
            attr.end_time = minutes_to_time(new_attr_en)
            attr.duration_min = dur
        except Exception:
            return items

    # Park lunch after the morning attraction (noon-ish).
    lunch_start = max(new_attr_en + 10, 12 * 60)
    lunch_dur = int(getattr(lunch, "duration_min", 0) or 45)
    lunch_dur = max(40, lunch_dur)
    try:
        items[lunch_idx] = lunch.model_copy(update={
            "start_time": minutes_to_time(lunch_start),
            "end_time": minutes_to_time(lunch_start + lunch_dur),
            "duration_min": lunch_dur,
        })
    except Exception:
        try:
            lunch.start_time = minutes_to_time(lunch_start)
            lunch.end_time = minutes_to_time(lunch_start + lunch_dur)
            lunch.duration_min = lunch_dur
        except Exception:
            pass

    # Ensure list order: attraction before lunch.
    if lunch_idx < first_attr_idx:
        lunch_item = items.pop(lunch_idx)
        # first_attr_idx shifted left by 1 after pop when lunch was before it
        insert_at = first_attr_idx  # after pop, attr is at first_attr_idx-1
        items.insert(insert_at, lunch_item)
    return items


def _push_early_lunch_to_noon(items: list) -> list:
    """FIX #256/#261 Wrocław: lunch before 11:45 → push to 12:00 (in-place)."""
    if not items:
        return items
    from app.domain.planner.time_utils import time_to_minutes, minutes_to_time
    for it in items:
        if getattr(it, "type", None) != ItemType.LUNCH_BREAK:
            continue
        st = getattr(it, "start_time", None)
        if not st:
            continue
        try:
            st_min = time_to_minutes(st)
        except Exception:
            continue
        if st_min >= 11 * 60 + 45:
            continue
        dur = int(getattr(it, "duration_min", 0) or 45)
        start_m = 12 * 60
        try:
            setattr(it, "start_time", minutes_to_time(start_m))
            setattr(it, "end_time", minutes_to_time(start_m + dur))
            if hasattr(it, "duration_min"):
                setattr(it, "duration_min", dur)
        except Exception:
            pass
        break
    return items

def _max_merged_free_time_cap(context: Dict[str, Any]) -> int:
    """FIX #221/#229/#230/#231/#233/#234: cap merged free_time — 12 min cities, 180 default, 300 Zakopane."""
    if context.get("is_zakopane_trip"):
        return 300
    if _is_urban_trip(context):
        return 12
    return 180


def _quality_first_trip(context: Optional[Dict[str, Any]]) -> bool:
    """FIX #275: 5+ day trips prefer quality over filling the window."""
    try:
        return int((context or {}).get("num_days") or 1) >= 5
    except (TypeError, ValueError):
        return False


def _early_close_enabled(context: Optional[Dict[str, Any]]) -> bool:
    """FIX #282: short city trips must not pad to 20:00 with empty free_time.

    Inject-skipping still uses `_quality_first_trip` (5+ only) so 2–3 day
    Wrocław days keep filling real holes.
    """
    if _quality_first_trip(context):
        return True
    try:
        from app.domain.planner.city_copy import is_city_tourism_trip
        return is_city_tourism_trip(context)
    except Exception:
        return False


def _is_winter_plan_context(context: Optional[Dict[str, Any]]) -> bool:
    """FIX #278: Feb/winter copy must not suggest ice cream or picnic blankets."""
    ctx = context or {}
    season = str(ctx.get("season") or "").strip().lower()
    if season == "winter":
        return True
    if season in ("summer", "spring", "autumn", "fall"):
        return False
    raw = ctx.get("date") or ctx.get("start_date") or ctx.get("trip_date")
    try:
        month = raw.month if hasattr(raw, "month") else int(str(raw)[5:7])
        return month in (11, 12, 1, 2, 3)
    except Exception:
        return False


def _ft_evening_starts_at(context: Optional[Dict[str, Any]]) -> int:
    """FIX #294: 'po zmroku' at 17:26 in July is still daylight."""
    ctx = context or {}
    season = str(ctx.get("season") or "").strip().lower()
    month = None
    raw = ctx.get("date") or ctx.get("start_date") or ctx.get("trip_date")
    try:
        month = raw.month if hasattr(raw, "month") else int(str(raw)[5:7])
    except Exception:
        month = None
    if season == "summer" or month in (6, 7, 8):
        return 20 * 60
    if season == "winter" or month in (12, 1, 2):
        return 16 * 60 + 30
    return 18 * 60


_WINTER_PICNIC_MARKERS = (
    "koc", "food truck", "foodtruck", "cień pod", "cien pod",
    "w ciepłe dni", "w cieple dni", "piknik", "kocem",
)


def _sanitize_winter_attraction_copy(
    name: Any,
    desc: Optional[str],
    tip: Optional[str],
    *,
    user: Optional[Dict[str, Any]] = None,
    context: Optional[Dict[str, Any]] = None,
) -> tuple:
    """FIX #282: Wyspa Słodowa in February must not get a summer picnic tip."""
    ctx = dict(context or {})
    if user:
        ctx.setdefault("date", user.get("start_date") or user.get("date"))
        ctx.setdefault("start_date", user.get("start_date") or user.get("date"))
        ctx.setdefault("season", user.get("season"))
    if not _is_winter_plan_context(ctx):
        return desc, tip
    nm = str(name or "").lower()
    wyspa = "wyspa słodowa" in nm or "wyspa slodowa" in nm
    winter_wyspa = (
        "Zimą wyspa jest na krótki spacer — ciepła kurtka i kawa "
        "w okolicy wystarczą."
    )

    def _scrub(text: Optional[str]) -> Optional[str]:
        if not text:
            return text
        if not any(k in text.lower() for k in _WINTER_PICNIC_MARKERS):
            return text
        return winter_wyspa if wyspa else None

    return _scrub(desc), _scrub(tip)


def _snap_day_end_up(end_min: int) -> int:
    """Round content end up to the next :00 / :30 (14:05 → 14:30)."""
    rem = int(end_min) % 30
    return int(end_min) if rem == 0 else int(end_min) + (30 - rem)


# Nominative → genitive for the day-1 early-close note
# ("odkrywanie Wrocławia", never "odkrywanie Wrocław").
_CITY_GENITIVE = {
    "wroclaw": "Wrocławia",
    "krakow": "Krakowa",
    "warszawa": "Warszawy",
    "poznan": "Poznania",
    "gdansk": "Gdańska",
    "gdynia": "Gdyni",
    "sopot": "Sopotu",
    "katowice": "Katowic",
    "zakopane": "Zakopanego",
    "karpacz": "Karpacza",
    "jelenia gora": "Jeleniej Góry",
    "klodzko": "Kłodzka",
    "kudowa-zdroj": "Kudowy-Zdroju",
    "polanica-zdroj": "Polanicy-Zdroju",
    "szklarska poreba": "Szklarskiej Poręby",
}


def _city_genitive(city: str) -> str:
    """FIX #280: inflect hub-city names used in 'odkrywanie X' copy."""
    raw = (city or "").strip()
    if not raw:
        return "miasta"
    folded = _fold_place_label(raw)
    return _CITY_GENITIVE.get(folded, raw)


def _early_close_note(
    items: list,
    *,
    day_num: int,
    num_days: int,
    city: str,
) -> Optional[str]:
    """FIX #278: honest copy when the day stops instead of fake free_time."""
    city_name = _city_genitive(city)
    names = [
        (getattr(it, "name", None) or "").strip()
        for it in items
        if _is_timeline_attraction(it)
    ]
    names = [n for n in names if n]
    blob = " ".join(n.lower() for n in names)
    lunch_end = None
    for it in items:
        if _item_type_value(it) != ItemType.LUNCH_BREAK.value:
            continue
        try:
            lunch_end = time_to_minutes(getattr(it, "end_time", None) or "")
        except Exception:
            continue
    after_lunch = []
    if lunch_end is not None:
        for it in items:
            if not _is_timeline_attraction(it):
                continue
            try:
                st = time_to_minutes(getattr(it, "start_time", None) or "")
            except Exception:
                continue
            if st >= lunch_end - 2:
                after_lunch.append(it)
    if day_num <= 1:
        if after_lunch:
            return None
        return (
            f"Dziś trochę spokojniej. Po zwiedzaniu centrum zostawiamy Ci "
            f"popołudnie na własne odkrywanie {city_name}."
        )
    if day_num >= 5 or (num_days >= 5 and day_num >= num_days - 2):
        return (
            "Dziś kończymy wcześniej. Po kilku intensywnych dniach "
            "zostawiamy Ci spokojne popołudnie."
        )
    bits = []
    if any(k in blob for k in ("aquapark", "park wodny", "wodny park")):
        bits.append("Aquaparku")
    if any(_item_type_value(it) == ItemType.LUNCH_BREAK.value for it in items):
        bits.append("lunchu")
    if any("muzeum" in n.lower() or "museum" in n.lower() for n in names):
        bits.append("muzeum")
    if not bits and names:
        bits = [names[-1]]
    joined = ", ".join(bits[:-1] + ([bits[-1]] if bits else []))
    if len(bits) >= 2:
        joined = f"{', '.join(bits[:-1])} i {bits[-1]}"
    elif bits:
        joined = bits[0]
    else:
        joined = "zwiedzaniu"
    if after_lunch:
        return None
    return (
        f"Spokojniejsze popołudnie: po {joined} zostawiamy Ci resztę dnia "
        f"na odpoczynek albo spontaniczne odkrywanie centrum."
    )


def _timeline_content_end_minutes(items: list) -> Optional[int]:
    """Last attraction/lunch end — ignore free_time, dinner stuffing, day markers."""
    last = None
    for it in items:
        tv = _item_type_value(it)
        if tv not in (ItemType.ATTRACTION.value, ItemType.LUNCH_BREAK.value):
            continue
        en = getattr(it, "end_time", None)
        if not en:
            continue
        try:
            last = max(last or 0, time_to_minutes(en))
        except Exception:
            continue
    return last


def _generate_day_title(day_items: list, day_num: int, *, excursion_hint: bool = False) -> str:
    """Generate a short descriptive title for a day based on its attractions.

    Rules:
    - 0 attractions  → "Dzień {day_num}"
    - 1 attraction   → name of that attraction
    - 2 attractions  → "Name1 i Name2"
    - 3+ attractions → "Name1, Name2 i więcej"
    """
    names = [
        (getattr(item, "name", None) or "").strip()
        for item in day_items
        if hasattr(item, "type") and item.type == ItemType.ATTRACTION
    ]
    names = [n for n in names if n]
    trailing_ft = 0
    last_attr_en = _timeline_content_end_minutes(day_items)
    if last_attr_en is not None:
        for item in day_items:
            if _item_type_value(item) != ItemType.FREE_TIME.value:
                continue
            try:
                st = time_to_minutes(getattr(item, "start_time", None) or "")
            except Exception:
                continue
            if st >= last_attr_en - 2:
                trailing_ft += int(getattr(item, "duration_min", 0) or 0)
    light = len(names) <= 2 and trailing_ft >= 90
    if not names:
        return (
            "Spokojniejszy dzień — czas na własne odkrywanie"
            if light else f"Dzień {day_num}"
        )
    if len(names) == 1:
        return (
            f"{names[0]} i spokojne popołudnie" if light else names[0]
        )
    if len(names) == 2:
        base = f"{names[0]} i {names[1]}"
    else:
        base = f"{names[0]}, {names[1]} i więcej"
    if excursion_hint:
        return f"{base} — propozycja wycieczki poza miasto"
    if light and len(names) == 2:
        return f"{base} — luźniejszy dzień"
    return base

def _day_note_matches_timeline(note: Optional[str], items: list) -> Optional[str]:
    """FIX #282: drop copy that claims an empty afternoon when POIs still follow."""
    if not note:
        return note
    low = note.lower()
    if not any(k in low for k in (
        "reszta dnia", "popołudnie na własne", "zostawiamy ci",
        "spokojne popołudnie", "luźniejsze popołudnie",
    )):
        return note
    lunch_end = None
    for it in items:
        if _item_type_value(it) != ItemType.LUNCH_BREAK.value:
            continue
        try:
            lunch_end = time_to_minutes(getattr(it, "end_time", None) or "")
        except Exception:
            continue
    if lunch_end is None:
        return note
    for it in items:
        if not _is_timeline_attraction(it):
            continue
        try:
            st = time_to_minutes(getattr(it, "start_time", None) or "")
        except Exception:
            continue
        if st >= lunch_end - 2:
            return None
    return note
