    def _strip_group_incompatible_attractions(
        self,
        items: List[Any],
        user: Optional[Dict[str, Any]],
        poi_by_id: Dict[str, Dict[str, Any]],
        context: Dict[str, Any],
        *,
        day_num: int = 0,
    ) -> List[Any]:
        """FIX #253 (Wrocław): a kids-only venue must never reach an adult plan.

        Target-group filtering was re-implemented in each injection path, and at
        least one of them let "Park Rozrywki Loopy's World" through for couples
        and seniors. This is a single safety net over the finished day, mirroring
        `_strip_out_of_season_attractions`.

        The FIX #252 exception stays intact: green POIs that Excel tags as
        couples/friends only are still allowed for solo and seniors travellers
        who asked for relaxation or nature.
        """
        if not user or not poi_by_id:
            return items
        from app.domain.scoring.family_fit import should_exclude_by_target_group
        from app.domain.scoring.preference_coverage import (
            is_strong_nature_coverage_poi,
            is_strong_relaxation_coverage_poi,
        )

        target_group = str(user.get("target_group") or "").lower()
        prefs = set(user.get("preferences") or [])
        wants_green = bool({"relaxation", "nature_landscape"} & prefs)

        out: List[Any] = []
        for it in items:
            if not _is_timeline_attraction(it):
                out.append(it)
                continue
            poi = poi_by_id.get(getattr(it, "poi_id", None) or "")
            if not poi:
                out.append(it)
                continue
            try:
                excluded = should_exclude_by_target_group(poi, user)
            except Exception:
                excluded = False
            if not excluded:
                out.append(it)
                continue

            kids_flag = poi.get("kids_only")
            is_kids_only = kids_flag is True or (
                isinstance(kids_flag, str) and kids_flag.lower() in ("true", "1", "yes")
            )
            is_green = False
            try:
                from app.domain.planner.poi_copy import (
                    category_is_green,
                    classify_poi_category,
                )

                is_green = category_is_green(classify_poi_category(poi)) and (
                    is_strong_nature_coverage_poi(poi)
                    or is_strong_relaxation_coverage_poi(poi)
                )
            except Exception:
                pass
            if (
                not is_kids_only
                and is_green
                and wants_green
                and target_group in ("solo", "seniors", "couples")
            ):
                out.append(it)
                continue
            print(
                f"[FIX #253] Day {day_num}: stripped '{getattr(it, 'name', '')}' "
                f"— niezgodna z grupą {target_group}"
            )
        return out

    def _strip_trip_duplicate_attractions(
        self,
        items: List[Any],
        trip_names_before_day: Optional[set],
        *,
        day_num: int = 0,
        trip_repeat_keys_before_day: Optional[set] = None,
    ) -> List[Any]:
        """FIX #253 (G2): an attraction seen on an earlier day cannot come back.

        Several rescue passes run with `cross_day_reuse=True`, which is how 5–7
        day plans started repeating Panorama Racławicka and Muzeum Przyrodnicze.
        A thinner day is better than a repeat — `_complete_day_coverage` then
        fills whatever this removes.

        Exact names alone are not enough: Excel often stores the same venue
        under two spellings, and the client audits fuzzy keys such as
        `kat_muzeum_hist` / `old town rynek główny`.
        """
        if not trip_names_before_day and not trip_repeat_keys_before_day:
            return items
        from app.domain.scoring.profile_poi_rules import poi_trip_repeat_key

        prior_keys = set(trip_repeat_keys_before_day or set())
        if trip_names_before_day:
            for nm in trip_names_before_day:
                rk = poi_trip_repeat_key(nm or "")
                if rk:
                    prior_keys.add(rk)
        out: List[Any] = []
        for it in items:
            if not _is_timeline_attraction(it):
                out.append(it)
                continue
            name = (getattr(it, "name", "") or "").strip().lower()
            rk = poi_trip_repeat_key(getattr(it, "name", "") or "")
            if name and trip_names_before_day and name in trip_names_before_day:
                print(
                    f"[FIX #253] Day {day_num}: stripped repeat "
                    f"'{getattr(it, 'name', '')}' (była w poprzednim dniu)"
                )
                continue
            if rk and rk in prior_keys:
                print(
                    f"[FIX #253] Day {day_num}: stripped repeat key {rk} "
                    f"'{getattr(it, 'name', '')}'"
                )
                continue
            out.append(it)
        return out

    def _strip_far_excursions_on_first_day(
        self,
        items: List[Any],
        poi_by_id: Dict[str, Dict[str, Any]],
        context: Dict[str, Any],
        *,
        day_num: int = 0,
    ) -> List[Any]:
        """FIX #253 (Wrocław): no out-of-town excursion on the arrival day.

        The client found Arboretum Wojsławice (zone C, ~50 km out) opening day
        one. Day one is an arrival day; far excursions belong later in the trip.

        FIX #261: client hard rule — "w dniu 1 nigdy nie robimy wyjazdów"
        (Wojsławice 67 km round-trip). Always strip zone-C / named day-trips
        on day 1; backfill later can refill the city day.
        """
        if day_num != 1 or int(context.get("num_days") or 1) < 2:
            return items
        _named_daytrip = (
            "wojsławice", "wojslawice", "arboretum", "topacz", "galowice",
            "powozów", "powozow", "oława", "olawa", "oławsk", "olawsk", "wena",
            "niemcza", "dolina tatarska",
            "ząbkowice", "zabkowice", "frankenstein",
            "brzegu", "piastów śląskich",
            "sochaczew", "żelazowa", "zelazowa", "lednick", "dziekanowic",
            "wiśnicz", "wisnicz", "eliaszówk", "eliaszowk",
            "rogalin", "puszczykow", "plaża miejska nad wartą",
            "plaza miejska nad wartą", "gniezno", "kórnik", "kornik",
        )
        out: List[Any] = []
        for it in items:
            if not _is_timeline_attraction(it):
                out.append(it)
                continue
            poi = poi_by_id.get(getattr(it, "poi_id", None) or "") or {}
            _nm_far = (getattr(it, "name", "") or "").lower()
            # FIX #255b: indoor water parks are the preference cover, not a
            # sightseeing excursion — keep them even on arrival day.
            if any(k in _nm_far for k in (
                "park wodny", "nemo", "wodny park", "aquapark",
            )) or ("tychy" in _nm_far and "wodny" in _nm_far):
                out.append(it)
                continue
            zone_c = str(poi.get("zone") or "").strip().upper() == "C"
            named = any(k in _nm_far for k in _named_daytrip)
            if zone_c or named:
                print(
                    f"[FIX #253/#261] Day 1: stripped far excursion "
                    f"'{getattr(it, 'name', '')}' "
                    f"({'zone C' if zone_c else 'named day-trip'})"
                )
                continue
            out.append(it)
        return out

    def _diversify_meal_suggestions(
        self,
        items: List[Any],
        context: Dict[str, Any],
        *,
        day_num: int = 0,
    ) -> List[Any]:
        """FIX #253 (G3): stop serving the same restaurant every single day.

        Meal suggestions were picked purely by proximity to the previous
        attraction, with no memory across days, so Wrocław plans kept landing on
        Taste and House of Spices. A trip-level set of already-served venues is
        carried in the context; a repeat is demoted in favour of the nearest
        restaurant that has not been used yet.
        """
        used = context.setdefault("trip_used_restaurants", set())
        restaurants = context.get("restaurants_available") or []

        meal_types = {
            ItemType.LUNCH_BREAK: "lunch",
            ItemType.DINNER_BREAK: "dinner",
        }
        out: List[Any] = []
        for idx, it in enumerate(items):
            meal_type = meal_types.get(getattr(it, "type", None))
            if not meal_type:
                out.append(it)
                continue
            suggestions = list(getattr(it, "suggestions", None) or [])
            if not suggestions:
                out.append(it)
                continue

            fresh = [s for s in suggestions if (s.name or "").lower() not in used]
            stale = [s for s in suggestions if (s.name or "").lower() in used]

            if not fresh and restaurants:
                # Every nearby suggestion is a repeat — widen the search.
                anchor = None
                for prev in reversed(items[:idx]):
                    if _is_timeline_attraction(prev) and getattr(prev, "lat", None):
                        anchor = {
                            "lat": getattr(prev, "lat", 0),
                            "lng": getattr(prev, "lng", 0),
                        }
                        break
                nearby = []
                if anchor:
                    from app.domain.planner.engine import (
                        _meal_restaurant_geo_ok,
                        _tiered_nearby_restaurants,
                    )

                    try:
                        nearby = _tiered_nearby_restaurants(
                            restaurants, anchor, context,
                            radii_km=(1.5, 3.0, 4.0),
                            limit=12,
                        )
                    except Exception:
                        nearby = []
                # FIX #254/#255: if proximity pool is exhausted, take unused geo-ok venues.
                if not nearby:
                    from app.domain.planner.engine import _meal_restaurant_geo_ok as _geo_ok255
                    nearby = [
                        r for r in restaurants
                        if _geo_ok255(r, anchor, context)
                    ] if anchor else list(restaurants)
                from app.domain.scoring.family_fit import (
                    restaurant_hard_denied_for_group as _hard257,
                    restaurant_matches_target_group as _match257,
                )
                _user257 = (context or {}).get("user") or {}
                if not _user257.get("target_group") and (context or {}).get("target_group"):
                    _user257 = {
                        **_user257,
                        "target_group": context.get("target_group"),
                    }
                _pref257 = [
                    c for c in nearby
                    if not _hard257(c, _user257)
                    and (
                        not _user257.get("target_group")
                        or _match257(c, _user257)
                    )
                ]
                _pool257 = _pref257 or [
                    c for c in nearby if not _hard257(c, _user257)
                ]
                for cand in _pool257:
                    nm = (cand.get("name") or "").lower()
                    if not nm or nm in used:
                        continue
                    mt = (cand.get("meal_type") or "").lower()
                    if mt and meal_type not in mt and mt not in ("all", "any"):
                        continue
                    fresh.append(
                        _restaurant_dict_to_suggestion(cand, meal_type)
                    )
                    if len(fresh) >= 2:
                        break

            ordered = fresh + stale
            if not ordered:
                out.append(it)
                continue
            # Prefer never-used; allow a venue at most twice — once on 7-day trips.
            primary = (ordered[0].name or "").lower()
            use_counts = context.setdefault("trip_restaurant_counts", {})
            try:
                n_days_meal = int((context or {}).get("num_days") or 0)
            except (TypeError, ValueError):
                n_days_meal = 0
            city_meal = str((context or {}).get("requested_city") or "").lower()
            war_meal = "warszawa" in city_meal or "warsaw" in city_meal
            max_uses = 1
            _sticky = (
                "u jakuba", "jakuba", "the cork", "cork", "just friends",
                "pierogarnia", "house of spices", "ida kuchnia", "ida ",
                "nolio", "lindley", "gospoda pod zygmuntem", "gospoda",
                "ciao italia", "smak róży", "smak rozy", "fajrant",
                "ratuszova", "miła", "mila", "pod bocianem",
            )
            if any(k in primary for k in _sticky):
                max_uses = 1
            if use_counts.get(primary, 0) >= max_uses and len(ordered) > 1:
                for alt in ordered[1:]:
                    alt_nm = (alt.name or "").lower()
                    if use_counts.get(alt_nm, 0) < max_uses:
                        ordered = [alt] + [s for s in ordered if s is not alt]
                        primary = alt_nm
                        break
            if ordered[0] is not suggestions[0]:
                print(
                    f"[FIX #253] Day {day_num}: {meal_type} swapped "
                    f"{suggestions[0].name} -> {ordered[0].name} (już użyta)"
                )
                try:
                    it = it.model_copy(update={"suggestions": ordered[:3]})
                except Exception:
                    pass
            used.add(primary)
            use_counts[primary] = use_counts.get(primary, 0) + 1
            out.append(it)
        return out

    def _day_fill_candidate(
        self,
        pool: List[Dict[str, Any]],
        *,
        user: Dict[str, Any],
        context: Dict[str, Any],
        slot_start_min: int,
        max_duration: int,
        used_ids: set,
        used_names: set,
        repeat_keys: set,
    ) -> Optional[Dict[str, Any]]:
        """FIX #253: pick one admissible POI for a hole in the day.

        Every existing injection path re-implemented its own (and slightly
        different) admissibility rules, which is how out-of-season gardens and
        kids-only venues slipped into adult plans. This gate applies all of them
        in one place: season, profile, target group, intensity, opening hours,
        city and trip-wide reuse.
        """
        from app.domain.planner.city_copy import poi_matches_city_filter
        from app.domain.planner.engine import (
            is_afternoon_only_poi,
            is_evening_only_poi,
        )
        from app.domain.scoring.family_fit import should_exclude_by_target_group
        from app.domain.scoring.intensity_scoring import should_exclude_by_intensity
        from app.domain.scoring.preference_coverage import poi_covers_preference_report
        from app.domain.scoring.profile_poi_rules import (
            poi_trip_repeat_key,
            profile_poi_score_delta,
            should_deny_poi_for_profile,
        )

        req_city = context.get("requested_city") or ""
        prefs = list(user.get("preferences") or [])
        best = None
        best_score = -1e9

        for poi in pool:
            pid = poi.get("id")
            name = (poi.get("name") or "").strip()
            if not pid or not name or pid in used_ids:
                continue
            if name.lower() in used_names:
                continue
            rk = poi_trip_repeat_key(name)
            if rk and rk in repeat_keys:
                continue
            if req_city and not poi_matches_city_filter(poi, req_city):
                continue
            if context.get("exclude_zone_c_pois") and str(
                poi.get("zone") or ""
            ).strip().upper() == "C":
                continue
            if self._poi_out_of_season(poi, context):
                continue
            # A neon gallery or a light show is pointless at 09:49 — the gate
            # applies the same time-of-day rules as the main planner.
            if slot_start_min < 17 * 60 and (
                is_evening_only_poi(poi) or is_evening_only_poi({"name": name})
            ):
                continue
            if slot_start_min < 14 * 60 and (
                is_afternoon_only_poi(poi) or is_afternoon_only_poi({"name": name})
            ):
                continue
            try:
                if should_deny_poi_for_profile(poi, user):
                    continue
                if should_exclude_by_target_group(poi, user):
                    continue
                if should_exclude_by_intensity(poi, user):
                    continue
            except Exception:
                continue
            duration = self._preferred_visit_minutes(poi)
            if duration > max_duration:
                continue
            try:
                if not is_open(
                    poi, slot_start_min, duration, context.get("season", "all"), context
                ):
                    continue
            except Exception:
                continue
            try:
                score = float(
                    profile_poi_score_delta(poi, user, context=context)
                )
            except Exception:
                score = 0.0
            for pref in prefs:
                try:
                    if poi_covers_preference_report(poi, pref):
                        score += 60.0
                except Exception:
                    pass
            if score > best_score:
                best_score = score
                best = poi
        return best

    # A paintball match, a karting session or an aquapark visit is a booked block
    # of time — Excel's time_min is the ticket minimum, not a realistic stay.
    # Client: "Zbyt krótki Paintball tylko 65 min i gokarty tylko 35 min,
    # Grabowy Labirynt tylko 35 minut."
    _BOOKED_ACTIVITY_FLOOR = {
        "shooting": 120,
        "motorsport": 90,
        "escape_room": 90,
        "maze": 60,
        "climbing": 90,
        "trampoline": 90,
        "aquapark": 150,
        "spa": 120,
    }

    def _booked_activity_floor(self, poi: Dict[str, Any]) -> int:
        """FIX #253: minimum realistic slot for a booked activity (0 if n/a)."""
        from app.domain.planner.poi_copy import classify_poi_category

        name = str(poi.get("name") or "").lower()
        # Name overrides beat Excel tags / wrong categories.
        if "labirynt" in name:
            return 60
        if any(k in name for k in ("paintball", "laser tag", "lasertag")):
            return 120
        if any(k in name for k in ("gokart", "karting", "quad")):
            return 90
        try:
            return int(
                self._BOOKED_ACTIVITY_FLOOR.get(classify_poi_category(poi), 0)
            )
        except Exception:
            return 0

    def _count_available_pois(
        self,
        pool: List[Dict[str, Any]],
        *,
        user: Dict[str, Any],
        context: Dict[str, Any],
        used_ids: set,
        used_names: set,
        repeat_keys: set,
    ) -> int:
        """FIX #253: how many admissible POIs the trip still has left."""
        from app.domain.planner.city_copy import poi_matches_city_filter
        from app.domain.scoring.family_fit import should_exclude_by_target_group
        from app.domain.scoring.profile_poi_rules import (
            poi_trip_repeat_key,
            should_deny_poi_for_profile,
        )

        req_city = context.get("requested_city") or ""
        count = 0
        for poi in pool:
            pid = poi.get("id")
            name = (poi.get("name") or "").strip()
            if not pid or not name or pid in used_ids:
                continue
            if name.lower() in used_names:
                continue
            rk = poi_trip_repeat_key(name)
            if rk and rk in repeat_keys:
                continue
            if req_city and not poi_matches_city_filter(poi, req_city):
                continue
            if self._poi_out_of_season(poi, context):
                continue
            try:
                if should_deny_poi_for_profile(poi, user):
                    continue
                if should_exclude_by_target_group(poi, user):
                    continue
            except Exception:
                continue
            count += 1
        return count

    def _preferred_visit_minutes(self, poi: Dict[str, Any]) -> int:
        """FIX #253: realistic visit length used when filling holes in a day."""
        try:
            tmin = int(float(poi.get("time_min") or poi.get("duration_min") or 60))
        except (TypeError, ValueError):
            tmin = 60
        try:
            tmax = int(float(poi.get("time_max") or poi.get("duration_max") or tmin))
        except (TypeError, ValueError):
            tmax = tmin
        tmax = max(tmax, tmin)

        floor = self._booked_activity_floor(poi)
        if floor:
            return max(tmin, min(tmax, floor))
        # Otherwise lean slightly above the minimum so days are not artificially thin.
        return max(tmin, min(tmax, tmin + (tmax - tmin) // 3))

    def _complete_day_coverage(
        self,
        items: List[Any],
        all_pois_dict: Optional[List[Dict[str, Any]]],
        context: Dict[str, Any],
        user: Optional[Dict[str, Any]],
        global_used_pois: Optional[set],
        trip_repeat_keys: Optional[set],
        *,
        day_num: int = 0,
        reclaimable_poi_ids: Optional[set] = None,
        trip_names_before_day: Optional[set] = None,
    ) -> List[Any]:
        """FIX #253 (G7/G9/G12): leave no unexplained hole in the day.

        The client reported 2–4 hour blanks mid-day, sightseeing that stopped at
        17:00 despite a 20:00 window, and days whose last attraction ended before
        lunch. Holes appeared because free_time was capped hard for urban trips
        while nothing replaced it. This pass walks the timeline and, for every
        hole, first tries a real attraction and only then falls back to a
        labelled free-time block, so the plan always accounts for the day.
        """
        if not items:
            return items
        day_end = context.get("day_end")
        day_start = context.get("day_start")
        if not day_end:
            return items
        try:
            end_limit = time_to_minutes(day_end)
            start_limit = time_to_minutes(day_start) if day_start else None
        except Exception:
            return items

        pool = all_pois_dict or []
        can_add_attractions = bool(pool and user)
        used_ids = {
            getattr(it, "poi_id", None)
            for it in items
            if getattr(it, "poi_id", None)
        }
        used_ids |= set(global_used_pois or set())
        used_names = {
            (getattr(it, "name", "") or "").strip().lower()
            for it in items
            if _is_timeline_attraction(it)
        }
        # Earlier days are an absolute ban — global_used alone is incomplete
        # (considered-then-dropped ids pollute it, scheduled names sometimes
        # missing), which is how fill→strip cycles emptied day 6/7 afternoons.
        for _nm_prior in (trip_names_before_day or set()):
            if _nm_prior:
                used_names.add(str(_nm_prior).strip().lower())
        repeat_keys = set(trip_repeat_keys or set())
        # Ids alone are not enough: the same venue can appear under two ids in
        # Excel, and the client explicitly asked for no repeats across 5–7 days.
        if global_used_pois and pool:
            _by_id = {p.get("id"): p for p in pool if p.get("id")}
            for _pid in global_used_pois:
                _p = _by_id.get(_pid)
                if _p and _p.get("name"):
                    used_names.add(str(_p["name"]).strip().lower())

        n_attrs_now = sum(1 for it in items if _is_timeline_attraction(it))
        # A thin day may take back what a later, still-unfinalized day can
        # spare. The later day drops the duplicate on its own turn, so the trip
        # keeps its variety and the empty afternoon disappears.
        # Never reclaim a name already served on an earlier day.
        _prior_lock = {
            str(n).strip().lower() for n in (trip_names_before_day or set()) if n
        }
        if reclaimable_poi_ids and n_attrs_now < 3 and int(
            context.get("num_days") or 1
        ) >= 5:
            _reclaim_names = {
                str(p.get("name") or "").strip().lower()
                for p in pool
                if p.get("id") in reclaimable_poi_ids and p.get("name")
            } - _prior_lock
            used_ids -= set(reclaimable_poi_ids)
            used_names -= _reclaim_names

        # Hard ceiling so a long window does not turn into a death march.
        max_attrs = 6 if (end_limit - (start_limit or 0)) < 600 else 7
        _fair253 = context.get("fair_share_attraction_cap")
        if _fair253:
            max_attrs = min(max_attrs, int(_fair253) + 1)
        n_attrs = sum(1 for it in items if _is_timeline_attraction(it))

        # Fair share: filling day 1 greedily used to starve day 7 (the client saw
        # a seventh day with a single attraction ending at 09:35). Spread what is
        # left of the city across the days that still need it.
        num_days = int(context.get("num_days") or 1)
        remaining_days = max(1, num_days - max(day_num, 1) + 1)
        adds_allowed = 4
        if can_add_attractions and remaining_days > 1:
            unused = self._count_available_pois(
                pool, user=user, context=context, used_ids=used_ids,
                used_names=used_names, repeat_keys=repeat_keys,
            )
            adds_allowed = max(2, unused // remaining_days)

        # A day filled to the brim is still wrong if it blows the wallet, so the
        # gap filler works within the same daily limit as the main planner.
        from app.domain.planner.engine import calculate_poi_cost_for_group
        daily_limit = (user or {}).get("daily_limit")
        day_cost = 0.0
        if daily_limit and pool:
            _cost_by_id = {p.get("id"): p for p in pool if p.get("id")}
            for it in items:
                pid = getattr(it, "poi_id", None)
                if not pid:
                    continue
                try:
                    day_cost += calculate_poi_cost_for_group(
                        _cost_by_id.get(pid, {}), user
                    )
                except Exception:
                    pass

        working = self._sort_items_by_time(items)
        added_attraction = False

        for _round in range(adds_allowed):
            holes = self._find_day_holes(working, end_limit, start_limit)
            big = [h for h in holes if h[1] - h[0] >= 75]
            if not big or not can_add_attractions or n_attrs >= max_attrs:
                break
            hole_start, hole_end = max(big, key=lambda h: h[1] - h[0])
            # Leave room on both sides for the legs the routing pass will add;
            # a tighter margin made those legs overlap the new stop.
            slot_start = hole_start + 20
            budget = (hole_end - slot_start) - 20
            if budget < 40:
                break
            poi = self._day_fill_candidate(
                pool,
                user=user,
                context=context,
                slot_start_min=slot_start,
                max_duration=budget,
                used_ids=used_ids,
                used_names=used_names,
                repeat_keys=repeat_keys,
            )
            if not poi:
                print(
                    f"[FIX #253] Day {day_num}: no candidate for "
                    f"{minutes_to_time(hole_start)}-{minutes_to_time(hole_end)} "
                    f"(pool={len(pool)}, used={len(used_ids)}, attrs={n_attrs})"
                )
                break
            if daily_limit:
                try:
                    poi_cost = calculate_poi_cost_for_group(poi, user)
                except Exception:
                    poi_cost = 0.0
                if day_cost + poi_cost > float(daily_limit):
                    print(
                        f"[FIX #253] Day {day_num}: skipped {poi.get('name')} "
                        f"(budżet {day_cost + poi_cost:.0f} > {daily_limit})"
                    )
                    used_ids.add(poi.get("id"))
                    continue
                day_cost += poi_cost
            new_item = self._generate_attraction_item(
                poi,
                minutes_to_time(slot_start),
                user,
                user.get("target_group", "solo"),
                context,
                None,
            )
            # _generate_attraction_item may stretch past the budget (booked
            # activities have a floor), which would leave the routing pass no
            # room for the leg into the next item.
            try:
                item_end = time_to_minutes(new_item.end_time)
                if item_end > hole_end - 20:
                    new_item.end_time = minutes_to_time(hole_end - 20)
                    new_item.duration_min = (hole_end - 20) - slot_start
            except Exception:
                pass
            working.append(new_item)
            working = self._sort_items_by_time(working)
            pid = poi.get("id")
            if pid:
                used_ids.add(pid)
                if global_used_pois is not None:
                    global_used_pois.add(pid)
            used_names.add((poi.get("name") or "").strip().lower())
            n_attrs += 1
            added_attraction = True
            print(
                f"[FIX #253] Day {day_num}: filled {hole_end - hole_start}min hole "
                f"with {poi.get('name')}"
            )

        working = self._stretch_attractions_into_empty_day(
            working, pool, end_limit, day_num=day_num,
        )
        # Free time is added only after transit routing: a block wedged between
        # two attractions makes the router treat them as non-adjacent, and the
        # leg joining them is never created.
        if added_attraction:
            working = self._strip_same_day_duplicate_attractions(working, day_num=day_num)
        return working

    def _stretch_attractions_into_empty_day(
        self,
        items: List[Any],
        pool: List[Dict[str, Any]],
        end_limit: int,
        *,
        day_num: int = 0,
    ) -> List[Any]:
        """FIX #253 (G9/G12): give thin days longer visits instead of dead time.

        When the city runs out of unused POIs, a day can end up with one 35-minute
        stop and eight empty hours. Excel gives every POI a range, so the honest
        answer is to spend the upper end of that range rather than to pad the
        afternoon with nothing. Only slack that is already free is used, so no
        item is pushed and no overlap is created.
        """
        attrs = [it for it in items if _is_timeline_attraction(it)]
        if not attrs or len(attrs) > 3:
            return items
        try:
            last_end = max(time_to_minutes(it.end_time) for it in attrs)
        except Exception:
            return items
        if end_limit - last_end < 120:
            return items

        by_id = {p.get("id"): p for p in pool if p.get("id")}
        ordered = self._sort_items_by_time(items)
        stretched = 0
        for idx, it in enumerate(ordered):
            if not _is_timeline_attraction(it):
                continue
            poi = by_id.get(getattr(it, "poi_id", None) or "")
            if not poi:
                continue
            try:
                tmax = int(float(poi.get("time_max") or poi.get("duration_max") or 0))
                start = time_to_minutes(it.start_time)
                end = time_to_minutes(it.end_time)
            except Exception:
                continue
            try:
                from app.domain.planner.engine import visit_duration_hard_cap
                _cap254 = visit_duration_hard_cap(poi)
                if _cap254 is not None:
                    tmax = min(tmax or _cap254, _cap254)
            except Exception:
                pass
            if tmax <= (end - start):
                continue
            next_start = end_limit
            for nxt in ordered[idx + 1:]:
                nst = getattr(nxt, "start_time", None)
                if not nst:
                    continue
                try:
                    next_start = time_to_minutes(nst)
                except Exception:
                    continue
                break
            new_end = min(start + tmax, next_start - 5, end_limit)
            if new_end - end < 15:
                continue
            it.end_time = minutes_to_time(new_end)
            it.duration_min = new_end - start
            stretched += 1
            print(
                f"[FIX #253] Day {day_num}: extended {getattr(it, 'name', '')} "
                f"to {it.end_time} (dzień był prawie pusty)"
            )
        return ordered if stretched else items

    # Poniżej tego progu dziura mieści się w akceptowanym wolnym czasie.
    # FIX #255: absorb mid-size holes (client: 25–40 min unexplained gaps) without
    # over-stretching meal/transit legs (regression at 18 → 90 min phantom travels).
    _GAP253_MIN = 25

    def _absorb_idle_gaps(
        self,
        items: List[Any],
        all_pois_dict: Optional[List[Dict[str, Any]]],
        context: Dict[str, Any],
        *,
        day_num: int = 0,
    ) -> List[Any]:
        """FIX #253 (G7/G9/G12): dead time next to a visit becomes more visiting.

        Once the city has no unused POI left for a hole, the honest answer is a
        longer stay at the stop already bordering it — not a two-hour blank and
        not a token free-time block. A leg parked at the front of a hole is
        first slid over to the stop it leads to, so the free minutes land next
        to the visit that can use them. Nothing is ever pushed later, no visit
        outgrows its Excel `time_max` or its closing time, so the rest of the
        day is left exactly as the earlier passes built it.
        """
        day_end = context.get("day_end")
        if not items or not day_end:
            return items
        try:
            end_limit = time_to_minutes(day_end)
            start_limit = (
                time_to_minutes(context["day_start"])
                if context.get("day_start")
                else None
            )
        except Exception:
            return items

        by_id = {p.get("id"): p for p in (all_pois_dict or []) if p.get("id")}
        by_name = {
            (p.get("name") or "").strip().lower(): p
            for p in (all_pois_dict or [])
            if p.get("name")
        }
        working = self._sort_items_by_time(items)
        absorbed = 0

        for _step in range(12):
            holes = [
                h
                for h in self._find_day_holes(working, end_limit, start_limit)
                if h[1] - h[0] >= self._GAP253_MIN
            ]
            moved = False
            for hole_start, hole_end in holes:
                if (
                    self._slide_transit_to_next_stop(
                        working, hole_start, hole_end,
                    )
                    or self._extend_visit_into_hole(
                        working, by_id, by_name, context, hole_start, hole_end,
                    )
                    or self._pull_next_visit_into_hole(
                        working, by_id, by_name, context, hole_start, hole_end,
                    )
                    or self._pull_next_meal_into_hole(
                        working, hole_start, hole_end,
                    )
                ):
                    moved = True
                    absorbed += 1
                    break
            if not moved:
                break
            working = self._sort_items_by_time(working)

        if absorbed:
            print(
                f"[FIX #253] Day {day_num}: absorbed {absorbed} idle gap(s) "
                f"into the surrounding stops"
            )
        return working

    def _slide_transit_to_next_stop(
        self,
        items: List[Any],
        hole_start: int,
        hole_end: int,
    ) -> bool:
        """FIX #253: park a leg next to the stop it leads to, not to the hole."""
        leg = None
        blockers: List[int] = []
        for it in items:
            st, en = getattr(it, "start_time", None), getattr(it, "end_time", None)
            if not st or not en:
                continue
            try:
                start, end = time_to_minutes(st), time_to_minutes(en)
            except Exception:
                continue
            if (
                getattr(it, "type", None) is ItemType.TRANSIT
                and end == hole_start
            ):
                leg = (it, start, end)
            elif end <= hole_start:
                blockers.append(end)
        if leg is None:
            return False
        it, start, end = leg
        duration = end - start
        new_start = hole_end - duration
        if new_start <= start:
            return False
        if blockers and new_start < max(blockers):
            return False
        it.start_time = minutes_to_time(new_start)
        it.end_time = minutes_to_time(hole_end)
        it.duration_min = duration
        return True

    def _extend_visit_into_hole(
        self,
        items: List[Any],
        by_id: Dict[str, Dict[str, Any]],
        by_name: Dict[str, Dict[str, Any]],
        context: Dict[str, Any],
        hole_start: int,
        hole_end: int,
    ) -> bool:
        """FIX #253: spend the empty minutes at the visit that borders them."""
        target = None
        for it in items:
            if not _is_timeline_attraction(it):
                continue
            en = getattr(it, "end_time", None)
            if not en:
                continue
            try:
                if time_to_minutes(en) == hole_start:
                    target = it
                    break
            except Exception:
                continue
        if target is None:
            return False

        poi = by_id.get(getattr(target, "poi_id", "") or "") or by_name.get(
            (getattr(target, "name", "") or "").strip().lower(), {}
        )
        try:
            start = time_to_minutes(target.start_time)
            cur_dur = max(0, hole_start - start)
            tmax = int(float(
                (poi or {}).get("time_max")
                or (poi or {}).get("duration_max")
                or cur_dur
                or 0
            ))
        except Exception:
            return False
        # FIX #253 G7: a 2–3 h blank after a visit that already hit time_max is
        # worse than a longer stay. Soft-cap the extension so the hole closes
        # without inventing an all-day museum marathon.
        hole_span = hole_end - hole_start
        soft_max = max(tmax, cur_dur)
        # FIX #253: close large blanks by extending the bordering visit.
        # FIX #254: named hard caps (Sky Tower / katedra / park) still win.
        if hole_span >= 90:
            soft_max = soft_max + min(hole_span, 150)
        try:
            from app.domain.planner.engine import visit_duration_hard_cap
            # Gap absorb: only extreme named caps (not every park→90).
            _cap254 = visit_duration_hard_cap(poi or {}, for_scheduling=False)
            if _cap254 is not None:
                soft_max = min(soft_max, _cap254)
        except Exception:
            pass
        new_end = min(start + soft_max, hole_end)
        if new_end - hole_start < 15:
            return False
        if poi and context.get("date") and (
            poi.get("opening_hours") or poi.get("Opening hours")
        ):
            try:
                if not is_open(
                    poi, start, new_end - start,
                    context.get("season", "all"), context,
                ):
                    return False
            except Exception:
                pass
        target.end_time = minutes_to_time(new_end)
        target.duration_min = new_end - start
        return True

    def _pull_next_meal_into_hole(
        self,
        items: List[Any],
        hole_start: int,
        hole_end: int,
    ) -> bool:
        """FIX #255: close attr→meal blanks by starting lunch/dinner earlier."""
        if hole_end - hole_start < 40:
            return False
        target = None
        for it in items:
            tv = _item_type_value(it)
            if tv not in (ItemType.LUNCH_BREAK.value, ItemType.DINNER_BREAK.value):
                continue
            st = getattr(it, "start_time", None)
            if not st:
                continue
            try:
                if time_to_minutes(st) == hole_end:
                    target = it
                    break
            except Exception:
                continue
        if target is None:
            return False
        try:
            dur = int(getattr(target, "duration_min", 0) or 0)
            if dur <= 0:
                dur = time_to_minutes(target.end_time) - time_to_minutes(target.start_time)
        except Exception:
            return False
        if dur < 20:
            return False
        # Keep lunch roughly in the 11:30–15:00 window; dinner after 16:30.
        tv = _item_type_value(target)
        new_start = hole_start
        if tv == ItemType.LUNCH_BREAK.value:
            new_start = max(hole_start, 11 * 60 + 30)
            if new_start >= 15 * 60:
                return False
        elif tv == ItemType.DINNER_BREAK.value:
            # Keep dinner in the evening window (FIX #240 pushes earlier dinners back).
            new_start = max(hole_start, 17 * 60)
            if new_start >= 19 * 60 + 30:
                return False
        if hole_end - new_start < 25:
            return False
        target.start_time = minutes_to_time(new_start)
        target.end_time = minutes_to_time(new_start + dur)
        target.duration_min = dur
        return True

    def _pull_next_visit_into_hole(
        self,
        items: List[Any],
        by_id: Dict[str, Dict[str, Any]],
        by_name: Dict[str, Dict[str, Any]],
        context: Dict[str, Any],
        hole_start: int,
        hole_end: int,
    ) -> bool:
        """FIX #253 G7: grow the next visit backward into a blank before it."""
        if hole_end - hole_start < 90:
            return False
        target = None
        for it in items:
            if not _is_timeline_attraction(it):
                continue
            st = getattr(it, "start_time", None)
            if not st:
                continue
            try:
                if time_to_minutes(st) == hole_end:
                    target = it
                    break
            except Exception:
                continue
        if target is None:
            return False
        poi = by_id.get(getattr(target, "poi_id", "") or "") or by_name.get(
            (getattr(target, "name", "") or "").strip().lower(), {}
        )
        try:
            end = time_to_minutes(target.end_time)
        except Exception:
            return False
        new_start = hole_start
        new_end = end
        if new_end - new_start < 15:
            return False
        if context.get("date") and poi:
            try:
                if not is_open(
                    poi, new_start, new_end - new_start,
                    context.get("season", "all"), context,
                ):
                    return False
            except Exception:
                pass
        target.start_time = minutes_to_time(new_start)
        target.end_time = minutes_to_time(new_end)
        target.duration_min = new_end - new_start
        return True

    def _cover_open_slots_with_free_time(
        self,
        items: List[Any],
        context: Dict[str, Any],
        *,
        day_num: int = 0,
        allow_partial: bool = False,
    ) -> List[Any]:
        """FIX #253: label short open slots — never turn a hole into dead time.

        Free time stays inside the limits the client already accepted (max 35 min
        per block, 45 min a day, see audit_free_time). A four-hour blank is a
        missing attraction, not a "wolny czas" block, so anything longer than the
        budget is left for the attraction passes rather than papered over.

        FIX #259: allow_partial (WRO/WAW) still labels the first ≤35 min of a
        larger hole so the client does not see a fully anonymous blank.
        """
        day_end = context.get("day_end")
        day_start = context.get("day_start")
        if not day_end or not items:
            return items
        try:
            end_limit = time_to_minutes(day_end)
            start_limit = time_to_minutes(day_start) if day_start else None
        except Exception:
            return items

        budget = self._FT253_MAX_TOTAL - sum(
            int(getattr(it, "duration_min", 0) or 0)
            for it in items
            if getattr(it, "type", None) is ItemType.FREE_TIME
        )
        if budget < 20:
            return items

        filler: List[Any] = []
        for idx, (hole_start, hole_end) in enumerate(
            self._find_day_holes(items, end_limit, start_limit)
        ):
            span = min(hole_end - hole_start, self._FT253_MAX_BLOCK, budget)
            # FIX #260: label short 12–19 min buffers explicitly (client: "14 i 13
            # minut niewidocznych buforów"). Longer holes keep the 20+ rule.
            _short_buf = 12 <= span < 20 and allow_partial
            if span < 20 and not _short_buf:
                continue
            # A block that only nibbles at the hole is the worst of both worlds:
            # the client still sees three dead hours, now labelled "wolny czas".
            # Leave such a hole alone — it belongs to the attraction passes.
            # FIX #259: WRO/WAW may still label the first chunk (allow_partial).
            if (hole_end - hole_start) - span > 20 and not allow_partial:
                continue
            # Don't paper over multi-hour blanks even with partial — attraction fill.
            if (hole_end - hole_start) > 150 and allow_partial:
                continue
            # FIX #260/#281: morning holes must not get "Popołudniowa przerwa"
            # or "Oddech w środku dnia" even when attractions sit later that day.
            if _short_buf:
                label, suggestions = ("Krótka przerwa / bufor", [])
                is_tech = True
            elif hole_start >= _ft_evening_starts_at(context):
                table = self._FT253_EVENING
                label, suggestions = table[(day_num + idx) % len(table)]
                is_tech = False
            elif hole_start < 10 * 60 + 30 and not any(
                _is_timeline_attraction(x)
                and time_to_minutes(getattr(x, "end_time", None) or "00:00") <= hole_start
                for x in items
            ):
                table = self._FT253_MORNING
                label, suggestions = table[(day_num + idx) % len(table)]
                is_tech = False
            else:
                table = (
                    self._FT253_AFTERNOON_WINTER
                    if _is_winter_plan_context(context)
                    else self._FT253_AFTERNOON
                )
                label, suggestions = table[(day_num + idx) % len(table)]
                is_tech = False
            filler.append(
                FreeTimeItem(
                    type=ItemType.FREE_TIME,
                    start_time=minutes_to_time(hole_start),
                    end_time=minutes_to_time(hole_start + span),
                    duration_min=span,
                    label=label,
                    suggestions=list(suggestions),
                    is_technical_buffer=is_tech,
                )
            )
            budget -= span
            if budget < 20:
                break
        if not filler:
            return items
        print(
            f"[FIX #253] Day {day_num}: covered {len(filler)} open slot(s) "
            f"with labelled free time"
        )
        return self._sort_items_by_time(items + filler)

    def _pull_attractions_into_anonymous_gaps(
        self,
        items: List[Any],
        *,
        day_num: int = 0,
        max_pull: int = 100,
    ) -> List[Any]:
        """FIX #259: slide the next attraction earlier to close 20–100 min blanks.

        Prefer moving the visit into the idle window over leaving anonymous dead
        air (client Wrocław retest: 55–105 min holes before Rynek / Panorama).
        """
        if not items:
            return items
        ordered = self._sort_items_by_time(list(items))
        out: List[Any] = []
        i = 0
        while i < len(ordered):
            cur = ordered[i]
            out.append(cur)
            if i + 1 >= len(ordered):
                break
            nxt = ordered[i + 1]
            # day_start often exposes only `time`, not end_time.
            cen = (
                getattr(cur, "end_time", None)
                or getattr(cur, "start_time", None)
                or getattr(cur, "time", None)
            )
            nst = getattr(nxt, "start_time", None)
            nen = getattr(nxt, "end_time", None)
            if not cen or not nst or not nen:
                i += 1
                continue
            try:
                gap = time_to_minutes(nst) - time_to_minutes(cen)
            except Exception:
                i += 1
                continue
            _from_day_start = _item_type_value(cur) == ItemType.DAY_START.value
            # Morning holes after a stripped first POI can exceed 2h — still pull.
            _pull_lim = 180 if _from_day_start else max_pull
            if gap < 20 or gap > _pull_lim:
                i += 1
                continue
            if _item_type_value(nxt) != ItemType.ATTRACTION.value:
                i += 1
                continue
            if _item_type_value(cur) == ItemType.DAY_END.value:
                i += 1
                continue
            # FIX #261: never drag Neon Side into the afternoon to close a hole.
            _pull_nm = (getattr(nxt, "name", "") or "").lower()
            if "neon" in _pull_nm:
                try:
                    if time_to_minutes(cen) < 17 * 60:
                        i += 1
                        continue
                except Exception:
                    i += 1
                    continue
            # day_start → first POI: leave a small buffer for the opening hop
            # (client: unreal 09:00→09:10 day-trips), but close large urban holes.
            anchor_end = time_to_minutes(cen)
            if _from_day_start:
                if gap < 45:
                    i += 1
                    continue
                anchor_end = min(anchor_end + 15, time_to_minutes(nst) - 5)
            dur = int(getattr(nxt, "duration_min", 0) or 0)
            if dur <= 0:
                dur = max(15, time_to_minutes(nen) - time_to_minutes(nst))
            new_st = anchor_end
            new_en = new_st + dur
            try:
                ordered[i + 1] = nxt.model_copy(update={
                    "start_time": minutes_to_time(new_st),
                    "end_time": minutes_to_time(new_en),
                    "duration_min": dur,
                })
                print(
                    f"[FIX #259] Day {day_num}: pulled "
                    f"{getattr(nxt, 'name', '?')} earlier by {gap}m"
                )
            except Exception:
                try:
                    nxt.start_time = minutes_to_time(new_st)
                    nxt.end_time = minutes_to_time(new_en)
                    nxt.duration_min = dur
                    ordered[i + 1] = nxt
                    print(
                        f"[FIX #259] Day {day_num}: pulled (inplace) "
                        f"{getattr(nxt, 'name', '?')} earlier by {gap}m"
                    )
                except Exception:
                    pass
            i += 1
        # Collapse consecutive free_time blocks left by cover+pull.
        merged: List[Any] = []
        for it in self._sort_items_by_time(ordered):
            if (
                merged
                and _item_type_value(merged[-1]) == ItemType.FREE_TIME.value
                and _item_type_value(it) == ItemType.FREE_TIME.value
            ):
                prev = merged[-1]
                try:
                    pst = time_to_minutes(prev.start_time)
                    nen2 = time_to_minutes(it.end_time)
                    merged[-1] = prev.model_copy(update={
                        "end_time": minutes_to_time(nen2),
                        "duration_min": max(5, nen2 - pst),
                    })
                    continue
                except Exception:
                    pass
            merged.append(it)
        return merged

    def _fit_transits_between_stops(
        self,
        items: List[Any],
        *,
        day_num: int = 0,
    ) -> List[Any]:
        """FIX #253: keep every leg inside the gap between the two stops it joins.

        Filling a hole with a new attraction makes the routing pass re-time the
        surrounding legs, and a re-timed leg could run past the stop it leads to
        ("przejazd 15:06-15:27" against an attraction starting 15:21). Shift the
        leg earlier when there is room, shorten it when there is not, and only
        drop it when the two stops are back to back.
        """
        ordered = self._sort_items_by_time(items)
        anchor_items: List[tuple] = []
        for it in ordered:
            if getattr(it, "type", None) in (
                ItemType.TRANSIT, ItemType.DAY_START, ItemType.DAY_END,
            ):
                continue
            st, en = getattr(it, "start_time", None), getattr(it, "end_time", None)
            if not st or not en:
                continue
            try:
                anchor_items.append((time_to_minutes(st), time_to_minutes(en), it))
            except Exception:
                continue
        if not anchor_items:
            return items
        anchors = [(a, b) for a, b, _ in anchor_items]

        out: List[Any] = []
        fitted = 0
        for it in ordered:
            if getattr(it, "type", None) is not ItemType.TRANSIT:
                out.append(it)
                continue
            try:
                start = time_to_minutes(it.start_time)
                end = time_to_minutes(it.end_time)
            except Exception:
                out.append(it)
                continue
            low = max(
                (a_end for a_start, a_end in anchors if a_end <= start), default=0
            )
            high = min(
                (a_start for a_start, a_end in anchors if a_start >= end),
                default=24 * 60,
            )
            # Anchors that straddle the leg decide the real room available.
            for a_start, a_end in anchors:
                if a_start < end and a_end > start:
                    if a_end <= end:
                        low = max(low, a_end)
                    if a_start >= start:
                        high = min(high, a_start)
            if high - low <= 0:
                # Back-to-back stops leave the leg nowhere to sit. Give it room
                # by ending the preceding visit a little earlier — dropping the
                # leg would leave two distant points with no way between them.
                need = max(1, end - start)
                prev = next(
                    (
                        item for a_start, a_end, item in anchor_items
                        if a_end == low and _is_timeline_attraction(item)
                        and (a_end - a_start) - need >= 30
                    ),
                    None,
                )
                if prev is not None:
                    new_prev_end = low - need
                    prev.end_time = minutes_to_time(new_prev_end)
                    prev.duration_min = new_prev_end - time_to_minutes(prev.start_time)
                    low = new_prev_end
                    high = low + need
                else:
                    # FIX #259: never keep a leg overlapping the previous stop —
                    # park a minimal leg right after prev_end (overlap heal / dinner
                    # push can absorb the squeeze on the next stop).
                    need = min(need, 15)
                    new_start = low if low > 0 else start
                    it.start_time = minutes_to_time(new_start)
                    it.end_time = minutes_to_time(new_start + need)
                    it.duration_min = need
                    fitted += 1
                    out.append(it)
                    continue
            span = min(end - start, high - low)
            new_start = min(max(start, low), high - span)
            new_end = new_start + span
            if (new_start, new_end) != (start, end):
                it.start_time = minutes_to_time(new_start)
                it.end_time = minutes_to_time(new_end)
                it.duration_min = span
                fitted += 1
            out.append(it)
        if fitted:
            print(f"[FIX #253] Day {day_num}: refitted {fitted} transit leg(s)")
        return self._sort_items_by_time(out)

    def _drop_free_time_with_large_adjacent_gaps(
        self,
        items: List[Any],
        *,
        max_adjacent: int = 90,
        day_num: int = 0,
    ) -> List[Any]:
        """FIX #255: remove free_time that still leaves a large idle neighbour gap."""
        timed = []
        for it in items:
            st, en = getattr(it, "start_time", None), getattr(it, "end_time", None)
            if not st or not en:
                continue
            try:
                timed.append((time_to_minutes(st), time_to_minutes(en), it))
            except Exception:
                continue
        timed.sort(key=lambda x: x[0])
        drop: set[int] = set()
        for i, (st, en, it) in enumerate(timed):
            if getattr(it, "type", None) is not ItemType.FREE_TIME:
                continue
            prev_end = timed[i - 1][1] if i > 0 else st
            next_start = timed[i + 1][0] if i + 1 < len(timed) else en
            gap_before = st - prev_end
            gap_after = next_start - en
            if gap_before > max_adjacent or gap_after > max_adjacent:
                drop.add(id(it))
                print(
                    f"[FIX #255] Day {day_num}: dropped free_time with adjacent "
                    f"idle {max(gap_before, gap_after)}m"
                )
        if not drop:
            return items
        return [it for it in items if id(it) not in drop]

    def _trim_free_time_over_real_items(
        self,
        items: List[Any],
        *,
        day_num: int = 0,
    ) -> List[Any]:
        """FIX #253: a free block must never sit on top of a real item.

        Free time is planned from the holes found before transits are re-routed,
        so a re-added leg can end up inside a block that already covers it — the
        day then shows "10:49-12:39 wolny czas" next to "10:49-11:03 przejazd".
        Trim the block to the free remainder, or drop it if nothing is left.

        A block that starts long after the previous activity ended is dropped
        outright: it is not a break between two things, it is a label pinned in
        the middle of dead time, and it made a single 107-minute blank read as
        "wolny czas" plus a blank on either side.
        """
        busy: List[tuple] = []
        for it in items:
            if getattr(it, "type", None) in (
                ItemType.FREE_TIME, ItemType.DAY_START, ItemType.DAY_END,
            ):
                continue
            st, en = getattr(it, "start_time", None), getattr(it, "end_time", None)
            if not st or not en:
                continue
            try:
                busy.append((time_to_minutes(st), time_to_minutes(en)))
            except Exception:
                continue
        if not busy:
            return items

        out: List[Any] = []
        trimmed = 0
        for it in items:
            if getattr(it, "type", None) is not ItemType.FREE_TIME:
                out.append(it)
                continue
            try:
                start = time_to_minutes(it.start_time)
                end = time_to_minutes(it.end_time)
            except Exception:
                out.append(it)
                continue
            for b_start, b_end in busy:
                if b_end <= start or b_start >= end:
                    continue
                if b_start <= start:
                    start = max(start, b_end)
                else:
                    end = min(end, b_start)
            if end - start < 15:
                trimmed += 1
                continue
            prev_end = max(
                (b_end for _b_start, b_end in busy if b_end <= start),
                default=None,
            )
            if prev_end is not None and start - prev_end > 45:
                trimmed += 1
                continue
            if (start, end) != (
                time_to_minutes(it.start_time), time_to_minutes(it.end_time)
            ):
                it.start_time = minutes_to_time(start)
                it.end_time = minutes_to_time(end)
                it.duration_min = end - start
                trimmed += 1
            out.append(it)
        if trimmed:
            print(
                f"[FIX #253] Day {day_num}: trimmed {trimmed} overlapping "
                f"free-time block(s)"
            )
        return self._sort_items_by_time(out)

    def _find_day_holes(
        self,
        items: List[Any],
        end_limit: int,
        start_limit: Optional[int],
        min_span: int = 20,
    ) -> List[tuple]:
        """FIX #253: uncovered [start, end] minute spans inside the day window."""
        spans: List[tuple] = []
        for it in items:
            if getattr(it, "type", None) in (ItemType.DAY_START, ItemType.DAY_END):
                continue
            st = getattr(it, "start_time", None)
            en = getattr(it, "end_time", None)
            if not st or not en:
                continue
            try:
                spans.append((time_to_minutes(st), time_to_minutes(en)))
            except Exception:
                continue
        if not spans:
            return []
        spans.sort()

        holes: List[tuple] = []
        # FIX #269: leading idle before the first item is a real hole
        # (was max(start_limit, first_span) which hid 09:00–12:00 gaps).
        cursor = start_limit if start_limit is not None else spans[0][0]
        for s, e in spans:
            if s > cursor:
                holes.append((cursor, min(s, end_limit)))
            cursor = max(cursor, e)
            if cursor >= end_limit:
                break
        if cursor < end_limit:
            holes.append((cursor, end_limit))
        return [(a, b) for a, b in holes if b - a >= min_span]

    def _enforce_day_transport_consistency(
        self,
        items: List[Any],
        user: Optional[Dict[str, Any]],
        context: Dict[str, Any],
        *,
        day_num: int = 0,
    ) -> List[Any]:
        """FIX #253 (G10): the car cannot teleport across a day.

        Every leg was previously routed on its own, so a day could read
        "car Pergola→Most Tumski", "walk Most Tumski→restauracja",
        "car restauracja→Hydropolis" — the car was left behind and reappeared.
        Once travellers pick the car up, every later leg of that day is a drive;
        legs before the first drive stay as they are (they happen on foot from
        the hotel). Durations are re-derived so a converted leg is never an
        absurd "10 min spacerem over 11 km".
        """
        if not items:
            return items

        transport_modes = list(
            (user or {}).get("transport_modes")
            or context.get("transport_modes")
            or []
        )
        has_car = context.get("has_car")
        if has_car is None:
            # transport_modes holds enum members, so compare on their value —
            # str(TransportMode.CAR) is "TransportMode.CAR", never "car".
            has_car = any(
                "car" in str(getattr(m, "value", m)).lower() for m in transport_modes
            )
            if not has_car:
                has_car = "car" in str(context.get("transport") or "").lower()
        if not has_car:
            return items

        transit_idx = [
            i for i, it in enumerate(items)
            if getattr(it, "type", None) == ItemType.TRANSIT
        ]
        if len(transit_idx) < 2:
            return items

        def _is_car(it: Any) -> bool:
            mode = getattr(it, "mode", None)
            return mode == TransitMode.CAR or str(
                getattr(mode, "value", mode)
            ).lower() == "car"

        first_car = next((i for i in transit_idx if _is_car(items[i])), None)
        if first_car is None:
            return items

        converted = 0
        for i in transit_idx:
            if i <= first_car:
                continue
            leg = items[i]
            if _is_car(leg):
                # FIX #254: even existing car legs must not keep estimated_walk.
                src = str(getattr(leg, "routing_source", "") or "")
                if src.endswith("walk") or src == "haversine":
                    try:
                        leg.routing_source = "estimated_road"
                    except Exception:
                        pass
                continue
            try:
                dist_km = float(getattr(leg, "distance_km", None) or 0)
            except (TypeError, ValueError):
                dist_km = 0.0
            # FIX #254: short urban hops stay on foot (client: car on 250–500 m).
            # Wrocław car-teleport after a walk-away is fixed via parking logistics.
            if dist_km <= 0 or dist_km < 1.5:
                continue
            old_mode = getattr(leg, "mode", None)
            leg.mode = TransitMode.CAR
            try:
                leg.routing_source = "estimated_road"
            except Exception:
                pass
            # A drive over the same distance is never slower than the walk it
            # replaces; keep the slot length and let the integrity pass re-flow.
            if dist_km > 0:
                drive_min = max(5, int(round(dist_km / 30.0 * 60)) + 5)
                cur = int(getattr(leg, "duration_min", 0) or 0)
                if cur > drive_min:
                    try:
                        start = time_to_minutes(leg.start_time)
                        leg.end_time = minutes_to_time(start + drive_min)
                        leg.duration_min = drive_min
                    except Exception:
                        pass
            converted += 1
            print(
                f"[FIX #256] Day {day_num}: transport consistency "
                f"{getattr(leg, 'from_location', '?')} -> "
                f"{getattr(leg, 'to_location', '?')}: {old_mode} -> car"
            )
        if converted:
            return self._sort_items_by_time(items)
        return items

    def _enforce_car_parking_logistics(
        self,
        items: List[Any],
        poi_coords: Dict[str, Any],
        context: Dict[str, Any],
        *,
        day_num: int = 0,
    ) -> List[Any]:
        """FIX #256/#259: car cannot teleport after the traveller walked away.

        Client (Wrocław): if auto was left at A and the party walked to B,
        the next car leg must start from A (return-to-car walk first), never
        magically from B.

        FIX #259: always walk the timeline in chronological order (unsorted
        item lists left Taste→Pergola teleports untouched), and never schedule
        the return-to-car walk on top of the preceding attraction.
        """
        from app.domain.models.plan import TransitItem, TransitMode
        from app.infrastructure.routing.haversine import haversine_km

        if not items:
            return items

        def _norm(n: str) -> str:
            return " ".join((n or "").strip().lower().split())

        def _is_car(it: Any) -> bool:
            mode = getattr(it, "mode", None)
            return mode == TransitMode.CAR or "car" in str(
                getattr(mode, "value", mode) or ""
            ).lower()

        def _is_walk(it: Any) -> bool:
            mode = getattr(it, "mode", None)
            return "walk" in str(getattr(mode, "value", mode) or "").lower()

        def _coords_for(name: str):
            if not name:
                return None
            hit = (poi_coords or {}).get(name) or (poi_coords or {}).get(name.strip())
            if hit and hit.get("lat") is not None and hit.get("lng") is not None:
                try:
                    return float(hit["lat"]), float(hit["lng"])
                except (TypeError, ValueError):
                    return None
            target = _norm(name)
            for k, v in (poi_coords or {}).items():
                if _norm(str(k)) == target and v:
                    try:
                        return float(v["lat"]), float(v["lng"])
                    except (TypeError, ValueError, KeyError):
                        continue
            return None

        def _last_occupied_end(seq: List[Any], before_min: int) -> int:
            """Latest end_time among items already emitted that end ≤ before_min+slack."""
            best = 0
            for prev in seq:
                en = getattr(prev, "end_time", None)
                if not en:
                    continue
                try:
                    em = time_to_minutes(en)
                except Exception:
                    continue
                if em <= before_min + 1:
                    best = max(best, em)
            return best

        # FIX #259: chronological scan — list order ≠ time order after inserts.
        ordered = self._sort_items_by_time(list(items))
        car_parked_at: str | None = None
        walked_away = False
        out: List[Any] = []
        has_car = bool((context or {}).get("has_car", True))
        later_car = any(
            _item_type_value(x) == ItemType.TRANSIT.value and _is_car(x)
            for x in ordered
        )
        # FIX #299: a walking prefix does not mean "car is at the next drive
        # origin". If they walked Cytadela→Iluzja then drove to Termy, the car
        # is still at Cytadela (or at the walk's from_location). Seed only when
        # a later car hop exists so walking-only days keep FIX #260 quiet.
        # FIX #302: do not seed from a ghost opening hop (Aula, not on the day).
        attr_names = self._day_attraction_names(ordered)
        if has_car and later_car:
            for seed_it in ordered:
                tv = _item_type_value(seed_it)
                if tv == ItemType.TRANSIT.value:
                    if _is_car(seed_it):
                        break
                    if _is_walk(seed_it):
                        frm0 = (
                            getattr(seed_it, "from_location", None) or ""
                        ).strip()
                        if frm0 and self._name_is_scheduled_attraction(
                            frm0, attr_names,
                        ):
                            car_parked_at = frm0
                            break
                        continue
                    continue
                if _is_timeline_attraction(seed_it):
                    nm0 = (getattr(seed_it, "name", None) or "").strip()
                    if nm0:
                        car_parked_at = nm0
                    break
            if not car_parked_at and attr_names:
                car_parked_at = attr_names[0]

        for it in ordered:
            if _item_type_value(it) != ItemType.TRANSIT.value:
                out.append(it)
                continue

            frm = (getattr(it, "from_location", None) or "").strip()
            to = (getattr(it, "to_location", None) or "").strip()

            if _is_walk(it):
                if car_parked_at:
                    if _norm(to) == _norm(car_parked_at):
                        # FIX #257b: walk back to the parked car clears the flag.
                        walked_away = False
                    elif (
                        _norm(frm) == _norm(car_parked_at)
                        or _norm(to) != _norm(car_parked_at)
                    ):
                        walked_away = True
                out.append(it)
                continue

            if not _is_car(it):
                out.append(it)
                continue

            # FIX #267: car.from already equals the park, but the party walked
            # away (Zamek→Ogród then car from Zamek with no return walk). Insert
            # return-to-car from the last occupied place first.
            if (
                car_parked_at
                and walked_away
                and frm
                and _norm(frm) == _norm(car_parked_at)
            ):
                last_place = None
                for prev in reversed(out):
                    if _is_timeline_attraction(prev):
                        last_place = (getattr(prev, "name", None) or "").strip()
                        break
                    if _item_type_value(prev) in (
                        ItemType.LUNCH_BREAK.value, ItemType.DINNER_BREAK.value,
                    ):
                        for sug in (getattr(prev, "suggestions", None) or [])[:1]:
                            rn = (getattr(sug, "name", None) or "").strip()
                            if rn:
                                last_place = rn
                                break
                        if last_place:
                            break
                if last_place and _norm(last_place) != _norm(car_parked_at):
                    already = any(
                        _item_type_value(x) == ItemType.TRANSIT.value
                        and _is_walk(x)
                        and _norm(getattr(x, "to_location", "") or "")
                        == _norm(car_parked_at)
                        and _norm(getattr(x, "from_location", "") or "")
                        == _norm(last_place)
                        for x in out
                    )
                    if not already:
                        frm = last_place  # fall through into insert below
                        # Force the teleport branch by mismatching from briefly.
                        # (handled by rewriting check below with walked frm)
                        try:
                            it = it.model_copy(update={"from_location": last_place})
                            frm = last_place
                        except Exception:
                            pass

            # FIX #257b: ANY car leg that does not start at the parked spot is a
            # teleport (missing walk/transit after return-to-car still counts).
            if (
                car_parked_at
                and frm
                and _norm(frm) != _norm(car_parked_at)
            ):
                c_from = _coords_for(frm)
                c_car = _coords_for(car_parked_at)
                walk_min = 10
                dist_km = 0.5
                if c_from and c_car:
                    try:
                        dist_km = max(
                            0.1,
                            haversine_km(c_from[0], c_from[1], c_car[0], c_car[1]),
                        )
                        walk_min = max(5, min(35, int(round(dist_km / 4.5 * 60)) + 2))
                    except Exception:
                        walk_min = 12
                try:
                    car_st = time_to_minutes(getattr(it, "start_time", None) or "12:00")
                except Exception:
                    car_st = 12 * 60
                car_dur = int(getattr(it, "duration_min", 0) or 0)
                if car_dur <= 0:
                    try:
                        car_dur = max(
                            5,
                            time_to_minutes(getattr(it, "end_time", None) or "12:05")
                            - car_st,
                        )
                    except Exception:
                        car_dur = 10
                # Never overlap the preceding attraction/meal — push the car leg.
                prev_end = _last_occupied_end(out, car_st)
                walk_st = max(prev_end, car_st - walk_min, 0)
                walk_en = walk_st + walk_min
                if walk_en > car_st:
                    car_st = walk_en
                    try:
                        it = it.model_copy(update={
                            "start_time": minutes_to_time(car_st),
                            "end_time": minutes_to_time(car_st + car_dur),
                            "duration_min": car_dur,
                        })
                    except Exception:
                        pass
                # Prefer retargeting an existing walk from this spot (avoids
                # duplicate overlapping return legs — FIX #257b / test-08).
                retargeted = False
                for j in range(len(out) - 1, -1, -1):
                    prev = out[j]
                    if _item_type_value(prev) != ItemType.TRANSIT.value:
                        if _is_timeline_attraction(prev):
                            break
                        continue
                    if not _is_walk(prev):
                        break
                    p_frm = (getattr(prev, "from_location", None) or "").strip()
                    p_to = (getattr(prev, "to_location", None) or "").strip()
                    if _norm(p_frm) == _norm(frm) or _norm(p_to) == _norm(frm):
                        try:
                            upd = {
                                "from_location": p_frm or frm,
                                "to_location": car_parked_at,
                                "end_time": minutes_to_time(walk_en),
                                "start_time": minutes_to_time(walk_st),
                                "duration_min": walk_en - walk_st,
                                "distance_km": round(dist_km, 3),
                                "routing_source": "estimated_walk",
                            }
                            out[j] = prev.model_copy(update=upd)
                        except Exception:
                            try:
                                prev.to_location = car_parked_at
                                prev.from_location = p_frm or frm
                            except Exception:
                                pass
                        retargeted = True
                        print(
                            f"[FIX #257b] Day {day_num}: retarget walk "
                            f"{p_frm}→{p_to} to return-to-car → {car_parked_at}"
                        )
                        break
                    break
                if not retargeted:
                    try:
                        ret = TransitItem(
                            start_time=minutes_to_time(walk_st),
                            end_time=minutes_to_time(walk_en),
                            duration_min=walk_en - walk_st,
                            mode=TransitMode.WALK,
                            from_location=frm,
                            to_location=car_parked_at,
                            distance_km=round(dist_km, 3),
                            routing_source="estimated_walk",
                        )
                        if c_from and c_car:
                            try:
                                ret = ret.model_copy(update={
                                    "geometry": [
                                        [c_from[1], c_from[0]],
                                        [c_car[1], c_car[0]],
                                    ],
                                    "geometry_latlng": [
                                        [c_from[0], c_from[1]],
                                        [c_car[0], c_car[1]],
                                    ],
                                })
                            except Exception:
                                pass
                        out.append(ret)
                        print(
                            f"[FIX #256/#259] Day {day_num}: return-to-car walk "
                            f"{frm} → {car_parked_at} ({walk_min}m @ "
                            f"{minutes_to_time(walk_st)})"
                        )
                    except Exception as exc:
                        print(f"[FIX #256] Day {day_num}: return-to-car failed: {exc}")
                try:
                    it = it.model_copy(update={"from_location": car_parked_at})
                except Exception:
                    try:
                        it.from_location = car_parked_at
                    except Exception:
                        pass
                walked_away = False

            out.append(it)
            if to:
                car_parked_at = to
                walked_away = False

        # FIX #260: end-of-day car state — if the party walked away from the
        # parked car and never drove again, add an explicit return-to-car walk
        # (client WAWA: car left at Manufaktura / Krasińskich while day ended
        # elsewhere on foot).
        if car_parked_at and walked_away:
            last_place = None
            last_end_min = None
            for prev in reversed(out):
                if _is_timeline_attraction(prev):
                    last_place = (getattr(prev, "name", None) or "").strip()
                    try:
                        last_end_min = time_to_minutes(
                            getattr(prev, "end_time", None) or "18:00"
                        )
                    except Exception:
                        last_end_min = 18 * 60
                    break
                if _item_type_value(prev) in (
                    ItemType.LUNCH_BREAK.value,
                    ItemType.DINNER_BREAK.value,
                    ItemType.FREE_TIME.value,
                ):
                    try:
                        last_end_min = time_to_minutes(
                            getattr(prev, "end_time", None) or last_end_min or "18:00"
                        )
                    except Exception:
                        pass
                    if _item_type_value(prev) != ItemType.FREE_TIME.value:
                        for sug in (getattr(prev, "suggestions", None) or [])[:1]:
                            rn = (getattr(sug, "name", None) or "").strip()
                            if rn:
                                last_place = rn
                                break
                    if last_place:
                        break
            if (
                last_place
                and last_end_min is not None
                and _norm(last_place) != _norm(car_parked_at)
            ):
                already = any(
                    _item_type_value(x) == ItemType.TRANSIT.value
                    and _is_walk(x)
                    and _norm(getattr(x, "to_location", "") or "") == _norm(car_parked_at)
                    and _norm(getattr(x, "from_location", "") or "") == _norm(last_place)
                    for x in out
                )
                if not already:
                    c_from = _coords_for(last_place)
                    c_car = _coords_for(car_parked_at)
                    walk_min = 12
                    dist_km = 0.6
                    if c_from and c_car:
                        try:
                            dist_km = max(
                                0.1,
                                haversine_km(
                                    c_from[0], c_from[1], c_car[0], c_car[1],
                                ),
                            )
                            walk_min = max(
                                5, min(40, int(round(dist_km / 4.5 * 60)) + 2)
                            )
                        except Exception:
                            walk_min = 12
                    try:
                        ret = TransitItem(
                            start_time=minutes_to_time(last_end_min),
                            end_time=minutes_to_time(last_end_min + walk_min),
                            duration_min=walk_min,
                            mode=TransitMode.WALK,
                            from_location=last_place,
                            to_location=car_parked_at,
                            distance_km=round(dist_km, 3),
                            routing_source="estimated_walk",
                        )
                        if c_from and c_car:
                            ret = ret.model_copy(update={
                                "geometry": [
                                    [c_from[1], c_from[0]],
                                    [c_car[1], c_car[0]],
                                ],
                                "geometry_latlng": [
                                    [c_from[0], c_from[1]],
                                    [c_car[0], c_car[1]],
                                ],
                            })
                        out.append(ret)
                        print(
                            f"[FIX #260] Day {day_num}: end-of-day return-to-car "
                            f"{last_place} → {car_parked_at} ({walk_min}m)"
                        )
                    except Exception as exc:
                        print(f"[FIX #260] end-of-day return-to-car failed: {exc}")

        return self._sort_items_by_time(out)

    def _cap_stretched_attraction_durations(
        self,
        items: List[Any],
        *,
        day_num: int = 0,
        user: Optional[Dict[str, Any]] = None,
    ) -> List[Any]:
        """FIX #256/#266: clamp visits past hard caps; floor iconic short stops."""
        from app.domain.planner.engine import visit_duration_hard_cap

        style = str((user or {}).get("travel_style") or "").lower()
        group = str((user or {}).get("target_group") or "").lower()

        ordered = self._sort_items_by_time(list(items))
        out: List[Any] = []
        i = 0
        while i < len(ordered):
            it = ordered[i]
            if not _is_timeline_attraction(it):
                out.append(it)
                i += 1
                continue
